	private ValueStore createLegacyFormat2ValueStore(File directory) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setTripleTermIndexes("spoc")
				.setInlineLiterals(false)
				.setLegacyReferenceCountRepairEnabled(true);
		StoreProperties properties = new StoreProperties(directory);
		if (!properties.load()) {
			properties.setVersion(Integer.toString(LmdbStoreFormat.LEGACY_VERSION))
					.setTripleIndexes("spoc,posc")
					.setTripleTermIndexes("spoc")
					.setInlineLiterals(false);
			properties.save();
			properties = new StoreProperties(directory);
			assertTrue("format-2 fixture properties are persisted", properties.load());
		}
		assertEquals(Integer.toString(LmdbStoreFormat.LEGACY_VERSION), properties.getVersion());
		assertEquals(Boolean.FALSE, properties.getInlineLiterals());
		assertFalse(properties.usesCoreDatatypeLiteralReferences());
		assertFalse(properties.usesCanonicalLanguageTags());
		assertFalse(properties.usesOrderedNumericIds());
		assertFalse(properties.usesZeroFractionDateTimeIds());
		assertTrue("legacy GC behavior is explicitly enabled", config.getLegacyReferenceCountRepairEnabled());
		LmdbStoreFormat format = LmdbStoreFormat.resolve(directory, properties, config);
		assertTrue(format.isLegacy());
		assertFalse(format.usesCoreDatatypeLiteralReferences());
		assertFalse(format.usesCanonicalLanguageTags());
		return new ValueStore(directory, properties, config, false, null, format, false);
	}

	@Test
	public void withDataUsesOneDeadlineObservationAfterAssociationAdmission() throws Exception {
		valueStore.startTransaction(true);
		long id = valueStore.storeValue(Values.iri("urn:test:deadline-observation"));
		valueStore.commit();

		QueryExecutionDeadline deadline = mock(QueryExecutionDeadline.class);
		when(deadline.remainingMillis()).thenReturn(TimeUnit.MINUTES.toMillis(1));

		try (QueryExecutionDeadline.Scope ignored = QueryExecutionDeadline.enterScopedContext(deadline)) {
			assertTrue(valueStore.withData(id, (address, length) -> length > 0L));
			// This path requires 13 reads: permit checks 2, timed barrier 2, association gate 2, capture 1,
			// native begin/renew 2, transaction creation 2, and scoped start 2. Keep the assertion as an upper bound.
			verify(deadline, atMost(13)).remainingMillis();
		}
	}

	@Test
	public void testCoreDatatypesAreSeededAndCachedOnStartup() throws Exception {
		valueStore.close();
		valueStore = createLegacyFormat2ValueStore(new File(dataDir, "values-format2-core-seed"));
		for (CoreDatatype.XSD datatype : CoreDatatype.XSD.values()) {
			assertCoreDatatypeIsSeededAndCached(datatype);
		}
		assertCoreDatatypeIsSeededAndCached(CoreDatatype.RDF.LANGSTRING);
	}

	private void assertCoreDatatypeIsSeededAndCached(CoreDatatype datatype) throws Exception {
		IRI datatypeIri = datatype.getIri();
		long id = valueStore.getId(datatypeIri);
		assertNotEquals("Expected startup-seeded ID for " + datatypeIri, LmdbValue.UNKNOWN_ID, id);
		assertEquals(datatypeIri, valueStore.cachedDatatype(id));
		assertSame(datatype, valueStore.cachedDatatypeCoreDatatype(id));
	}

	@Test
	public void testDisableInlineLiteralsUsesStoredIds() throws Exception {
		valueStore.close();
		LmdbStoreConfig config = new LmdbStoreConfig();
		Resource implNode = Values.bnode();
		Model configModel = new ModelBuilder().add(implNode, INLINE_LITERALS, Values.literal(false)).build();
		config.parse(configModel, implNode);
		assertFalse("inline literals should be disabled after parsing config", config.getInlineLiterals());
		valueStore = createValueStore(new File(dataDir, "inline-disabled-values"), config);
		assertFalse("the opened value format must honor inlineLiterals=false",
				valueStore.getFormat().inlinesLiterals());
		Literal literal = Values.literal("inline");
		valueStore.startTransaction(true);
		long id = valueStore.storeValue(literal);
		valueStore.commit();
		assertFalse("small literals should not be inlined when disabled", ValueIds.isInlined(id));
		assertEquals(literal, valueStore.getValue(id));
	}

	@Test
	public void batchResolveValuesUsesSingleReadTransaction() throws Exception {
		CountingValueStore countingValueStore = new CountingValueStore(new File(dataDir, "counting-values"),
				new LmdbStoreConfig());
		try {
			LmdbBNode first = countingValueStore.createBNode("batch-first");
			LmdbBNode second = countingValueStore.createBNode("batch-second");
			countingValueStore.startTransaction(true);
			long firstId = countingValueStore.storeValue(first);
			long secondId = countingValueStore.storeValue(second);
			countingValueStore.commit();
			LmdbValue lazyFirst = countingValueStore.getLazyValue(firstId);
			LmdbValue lazySecond = countingValueStore.getLazyValue(secondId);
			assertFalse(isInitialized(lazyFirst));
			assertFalse(isInitialized(lazySecond));
			QueryBindingSet firstRow = row("value", Values.literal("already-initialized"));
			QueryBindingSet secondRow = row("value", lazySecond);
			QueryBindingSet thirdRow = row("value", lazyFirst);
			long admissionsBefore = countingValueStore.getTxnManager().ordinaryAdmissions()
					+ countingValueStore.getTxnManager().reservedAdmissions();
			try (LmdbValueMaterializingIteration iteration = new LmdbValueMaterializingIteration(
					bindingSets(firstRow, secondRow, thirdRow), 16)) {
				assertSame(firstRow, iteration.next());
				assertSame(secondRow, iteration.next());
				assertSame(thirdRow, iteration.next());
				assertFalse(iteration.hasNext());
			}
			assertTrue(isInitialized(lazyFirst));
			assertTrue(isInitialized(lazySecond));
			assertEquals("buffered same-revision values should share one read transaction", 1,
					countingValueStore.getTxnManager().ordinaryAdmissions()
							+ countingValueStore.getTxnManager().reservedAdmissions() - admissionsBefore);
		} finally {
			countingValueStore.close();
		}
	}

	@Test
	public void batchResolveValuesUsesCursorWalkForSortedExternalIds() throws Exception {
		CountingValueStore countingValueStore = new CountingValueStore(new File(dataDir, "cursor-values"),
				new LmdbStoreConfig());
		try {
			LmdbBNode first = countingValueStore.createBNode("cursor-first");
			LmdbBNode second = countingValueStore.createBNode("cursor-second");
			LmdbBNode third = countingValueStore.createBNode("cursor-third");
			countingValueStore.startTransaction(true);
			long firstId = countingValueStore.storeValue(first);
			long secondId = countingValueStore.storeValue(second);
			long thirdId = countingValueStore.storeValue(third);
			countingValueStore.commit();
			LmdbValue lazyFirst = countingValueStore.getLazyValue(firstId);
			LmdbValue lazySecond = countingValueStore.getLazyValue(secondId);
			LmdbValue lazyThird = countingValueStore.getLazyValue(thirdId);
			assertFalse(isInitialized(lazyFirst));
			assertFalse(isInitialized(lazySecond));
			assertFalse(isInitialized(lazyThird));
			LmdbValue[] lazyValues = { lazyThird, lazyFirst, lazySecond };
			int[] sortedOrder = { 1, 2, 0 };
			long admissionsBefore = countingValueStore.getTxnManager().ordinaryAdmissions()
					+ countingValueStore.getTxnManager().reservedAdmissions();
			countingValueStore.batchCursorOpenCount = 0;
			countingValueStore.batchCursorSeekCount = 0;
			countingValueStore.batchCursorNextCount = 0;
			lazyFirst.getValueStoreRevision().resolveValues(lazyValues, sortedOrder, lazyValues.length);
			assertTrue(isInitialized(lazyFirst));
			assertTrue(isInitialized(lazySecond));
			assertTrue(isInitialized(lazyThird));
			assertEquals("batch resolve should still use one read transaction", 1,
					countingValueStore.getTxnManager().ordinaryAdmissions()
							+ countingValueStore.getTxnManager().reservedAdmissions() - admissionsBefore);
			assertEquals("sorted batch should open one cursor", 1, countingValueStore.batchCursorOpenCount);
			assertEquals("dense sorted IDs should seek once, then walk", 1, countingValueStore.batchCursorSeekCount);
			assertEquals("dense sorted IDs should walk the cursor for remaining values", 2,
					countingValueStore.batchCursorNextCount);
		} finally {
			countingValueStore.close();
		}
	}

	@Test
	public void batchResolveValuesAvoidsByteBufferWrappersForCursorData() throws Exception {
		CountingValueStore countingValueStore = new CountingValueStore(new File(dataDir, "pointer-values"),
				new LmdbStoreConfig().setInlineLiterals(false));
		try {
			LmdbIRI iri = countingValueStore.createIRI("urn:batch:", "pointer-iri");
			LmdbBNode bnode = countingValueStore.createBNode("pointer-bnode");
			LmdbLiteral literal = countingValueStore.createLiteral("pointer-label-" + "x".repeat(512), "en");
			countingValueStore.startTransaction(true);
			long iriId = countingValueStore.storeValue(iri);
			long bnodeId = countingValueStore.storeValue(bnode);
			long literalId = countingValueStore.storeValue(literal);
			countingValueStore.commit();
			LmdbValue lazyIri = countingValueStore.getLazyValue(iriId);
			LmdbValue lazyBNode = countingValueStore.getLazyValue(bnodeId);
			LmdbValue lazyLiteral = countingValueStore.getLazyValue(literalId);
			assertFalse(isInitialized(lazyIri));
			assertFalse(isInitialized(lazyBNode));
			assertFalse(isInitialized(lazyLiteral));
			LmdbValue[] lazyValues = { lazyLiteral, lazyIri, lazyBNode };
			long[] ids = { literalId, iriId, bnodeId };
			int[] sortedOrder = sortedOrder(ids);
			countingValueStore.batchKeyBufferWrapCount = 0;
			countingValueStore.batchValueBufferWrapCount = 0;
			countingValueStore.batchDataBufferSliceCount = 0;
			lazyIri.getValueStoreRevision().resolveValues(lazyValues, sortedOrder, lazyValues.length);
			assertEquals(iri, lazyIri);
			assertEquals(bnode, lazyBNode);
			assertEquals(literal, lazyLiteral);
			assertEquals("batch cursor key comparisons should not allocate ByteBuffer wrappers", 0,
					countingValueStore.batchKeyBufferWrapCount);
			assertEquals("batch value decode should not allocate MDBVal ByteBuffer wrappers", 0,
					countingValueStore.batchValueBufferWrapCount);
			assertEquals("batch value decode should not slice ByteBuffers", 0,
					countingValueStore.batchDataBufferSliceCount);
		} finally {
			countingValueStore.close();
		}
	}

	@Test
	public void batchResolveLazyValuesUnwrapsRevisionAfterResolve() throws Exception {
		CountingValueStore countingValueStore = new CountingValueStore(new File(dataDir, "unwrap-values"),
				new LmdbStoreConfig());
		try {
			LmdbBNode first = countingValueStore.createBNode("unwrap-first");
			LmdbBNode second = countingValueStore.createBNode("unwrap-second");
			countingValueStore.startTransaction(true);
			long firstId = countingValueStore.storeValue(first);
			long secondId = countingValueStore.storeValue(second);
			countingValueStore.commit();
			LmdbValue lazyFirst = countingValueStore.getLazyValue(firstId);
			LmdbValue lazySecond = countingValueStore.getLazyValue(secondId);
			ValueStoreRevision lazyRevision = lazyFirst.getValueStoreRevision();
			assertSame(lazyRevision, lazySecond.getValueStoreRevision());
			assertFalse(countingValueStore.getRevision() == lazyRevision);
			Method resolveValues = lazyRevision.getClass()
					.getMethod("resolveValues", LmdbValue[].class, int[].class, int.class);
			LmdbValue[] lazyValues = { lazyFirst, lazySecond };
			resolveValues.invoke(lazyRevision, new Object[] { lazyValues, new int[] { 0, 1 }, lazyValues.length });
			assertTrue(isInitialized(lazyFirst));
			assertTrue(isInitialized(lazySecond));
			assertSame(countingValueStore.getRevision(), lazyFirst.getValueStoreRevision());
			assertSame(countingValueStore.getRevision(), lazySecond.getValueStoreRevision());
		} finally {
			countingValueStore.close();
		}
	}

	@Test
	public void storeValuesStoresMultipleValuesWithSingleReadTransaction() throws Exception {
		CountingValueStore countingValueStore = new CountingValueStore(new File(dataDir, "store-values"),
				new LmdbStoreConfig());
		try {
			Value[] values = { countingValueStore.createBNode("batch-store-first"),
					countingValueStore.createBNode("batch-store-second"),
					countingValueStore.createBNode("batch-store-third") };
			long[] ids = new long[values.length];
			countingValueStore.startTransaction(true);
			boolean committed = false;
			try {
				countingValueStore.readTransactionCount = 0;
				invokeStoreValues(countingValueStore, values, ids, values.length);
				assertEquals("multiple missing values should share one transaction wrapper", 1,
						countingValueStore.readTransactionCount);
				countingValueStore.commit();
				committed = true;
			} finally {
				if (!committed) {
					countingValueStore.rollback();
				}
			}
			for (int i = 0; i < values.length; i++) {
				assertNotEquals(LmdbValue.UNKNOWN_ID, ids[i]);
				assertEquals(values[i], countingValueStore.getValue(ids[i]));
			}
		} finally {
			countingValueStore.close();
		}
	}

