	/**
	 * Stores all but the last value in one transaction and the last value in a second one, so the reference counts of
	 * shared datatypes, namespaces and triple-term components must add to the counts persisted by the first.
	 */
	private long[] storeInTwoTransactions(Value... values) throws IOException {
		long[] ids = new long[values.length];
		valueStore.startTransaction(true);
		for (int i = 0; i < values.length - 1; i++) {
			ids[i] = valueStore.storeValue(values[i]);
		}
		valueStore.commit();
		valueStore.startTransaction(true);
		ids[values.length - 1] = valueStore.storeValue(values[values.length - 1]);
		valueStore.commit();
		return ids;
	}

	@Test
	public void testLegacyReferenceCountsAreRecountedOnOpen() throws Exception {
		IRI datatype = Values.iri("http://example.org/datatypes#custom");
		IRI subject = Values.iri("http://example.org/terms/subject");
		IRI predicate = Values.iri("http://example.org/terms/predicate");
		List<Value> values = new ArrayList<>();
		for (String name : List.of("first", "second", "third", "fourth")) {
			values.add(Values.literal(name, datatype));
			values.add(Values.iri("http://example.org/refcount/" + name));
			values.add(Values.tripleTerm(subject, predicate, Values.iri("http://example.org/objects/" + name)));
		}
		long[] ids = new long[values.size()];
		valueStore.startTransaction(true);
		for (int i = 0; i < ids.length; i++) {
			ids[i] = valueStore.storeValue(values.get(i));
		}
		valueStore.commit();
		LmdbStoreFormat seededFormat = valueStore.getFormat();
		assertEquals(LmdbStoreFormat.CURRENT_VERSION, seededFormat.getVersion());
		assertTrue(seededFormat.usesCoreDatatypeLiteralReferences());
		assertTrue(seededFormat.usesCanonicalLanguageTags());
		assertTrue(seededFormat.usesZeroFractionDateTimeIds());
		valueStore.close();
		assertClosedCleanRefCountMarker(new File(dataDir, "values"));
		assertTrue("fixture: the store persisted reference counts", rewritePersistedRefCountsToOne() > 0);
		inspectNativeStore(new File(dataDir, "values"), (stack, txn) -> {
			assertMigrationMarkerAbsent(stack, txn);
			return null;
		});
		valueStore = createValueStore();
		assertResolvedCurrentFormatCapabilities(seededFormat, valueStore.getFormat());
		// datatype, namespace, subject and predicate stay referenced by the other literals, IRIs and triple terms
		assertEquals("only the object of the collected triple term is unreferenced",
				Set.of(valueStore.getId(Values.iri("http://example.org/objects/first"))),
				gcIdsInTransaction(ids[0], ids[1], ids[2]));
		valueStore.close();
		File directory = new File(dataDir, "values");
		long firstCleanTransaction = assertClosedCleanRefCountMarker(directory);
		Map<Long, Long> firstCounts = closedNativeRefCounts(directory);
		valueStore = createValueStore();
		assertResolvedCurrentFormatCapabilities(seededFormat, valueStore.getFormat());
		for (int i = 3; i < ids.length; i++) {
			assertEquals("every surviving mapping keeps its exact ID on the second open", ids[i],
					valueStore.getId(values.get(i)));
			assertEquals(values.get(i), valueStore.getValue(ids[i]));
		}
		valueStore.close();
		assertTrue("each clean marker qualifies its own later native generation",
				assertClosedCleanRefCountMarker(directory) > firstCleanTransaction);
		assertEquals("the completed recount stays exact across a second open", firstCounts,
				closedNativeRefCounts(directory));
	}

	/**
	 * Rewrites every persisted reference count to 1: the state a store written while adding a reference ignored the
	 * persisted count is left in when its last transaction referenced each id once.
	 */
	private int rewritePersistedRefCountsToOne() throws IOException {
		try (MemoryStack stack = stackPush()) {
			PointerBuffer pp = stack.mallocPointer(1);
			E(mdb_env_create(pp));
			long env = pp.get(0);
			try {
				E(mdb_env_set_maxdbs(env, 6 + 12));
				E(mdb_env_open(env, new File(dataDir, "values").getAbsolutePath(), MDB_NOTLS, 0664));
				E(mdb_txn_begin(env, NULL, 0, pp));
				long txn = pp.get(0);
				IntBuffer refCountsDbi = stack.mallocInt(1);
				E(mdb_dbi_open(txn, "ref_counts", 0, refCountsDbi));
				E(mdb_cursor_open(txn, refCountsDbi.get(0), pp));
				long cursor = pp.get(0);
				MDBVal keyVal = MDBVal.calloc(stack);
				MDBVal dataVal = MDBVal.calloc(stack);
				ByteBuffer one = stack.malloc(Long.BYTES + 1);
				Varint.writeUnsigned(one, 1);
				MDBVal oneVal = MDBVal.calloc(stack).mv_data(one.flip());
				int rewritten = 0;
				// Legacy environments did not have develop's atomic native recount marker.
				E(mdb_del(txn, refCountsDbi.get(0), MDBVal.calloc(stack).mv_data(stack.bytes((byte) 0)), null));
				int rc = mdb_cursor_get(cursor, keyVal, dataVal, MDB_FIRST);
				while (rc == MDB_SUCCESS) {
					E(mdb_cursor_put(cursor, keyVal, oneVal, MDB_CURRENT));
					rewritten++;
					rc = mdb_cursor_get(cursor, keyVal, dataVal, MDB_NEXT);
				}
				mdb_cursor_close(cursor);
				E(mdb_txn_commit(txn));
				return rewritten;
			} finally {
				mdb_env_close(env);
			}
		}
	}

	/**
	 * Collects {@code ids} and returns the ids whose reference count dropped to zero as a consequence.
	 */
	private Set<Long> gcIdsInTransaction(long... ids) throws IOException {
		Set<Long> nextIds = new HashSet<>();
		valueStore.startTransaction(true);
		valueStore.gcIds(Arrays.stream(ids).boxed().collect(Collectors.toSet()), nextIds);
		valueStore.commit();
		return nextIds;
	}

	@Test
	public void testDisableGc() throws Exception {
		final Random random = new Random(1337);
		final LmdbValue[] values = new LmdbValue[1000];
		ValueStore disabledGcValueStore = new ValueStore(new File(dataDir, "values"),
				new LmdbStoreConfig().setValueEvictionInterval(-1));
		try {
			disabledGcValueStore.startTransaction(true);
			for (int i = 0; i < values.length; i++) {
				values[i] = disabledGcValueStore.createLiteral("This is a random literal:" + random.nextLong());
				disabledGcValueStore.storeValue(values[i]);
			}
			disabledGcValueStore.commit();
			final ValueStoreRevision revBefore = disabledGcValueStore.getRevision();
			disabledGcValueStore.startTransaction(true);
			Set<Long> ids = new HashSet<>();
			for (int i = 0; i < 30; i++) {
				ids.add(values[i].getInternalID());
			}
			disabledGcValueStore.gcIds(ids, new HashSet<>());
			disabledGcValueStore.commit();
			final ValueStoreRevision revAfter = disabledGcValueStore.getRevision();
			assertEquals("revisions must NOT change since GC is disabled", revBefore, revAfter);
			Arrays.fill(values, null);
			disabledGcValueStore.unusedRevisionIds.add(revBefore.getRevisionId());
			disabledGcValueStore.forceEvictionOfValues();
			disabledGcValueStore.startTransaction(true);
			disabledGcValueStore.commit();
			disabledGcValueStore.startTransaction(true);
			for (int i = 0; i < 30; i++) {
				LmdbValue value = disabledGcValueStore.createLiteral("This is a random literal:" + random.nextLong());
				values[i] = value;
				disabledGcValueStore.storeValue(value);
				ids.remove(value.getInternalID());
			}
			disabledGcValueStore.commit();
			assertNotEquals("IDs should NOT have been reused since GC is disabled", Collections.emptySet(), ids);
		} finally {
			disabledGcValueStore.close();
			valueStore = createValueStore();
		}
	}

