	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	public void testInterruptedTripleTermIteratorReturnsReaderPermit(boolean rangeSearch) throws Exception {
		valueStore.startTransaction(true);
		long subjectId = valueStore.storeValue(RDF.TYPE);
		valueStore.commit();
		TxnManager txnManager = valueStore.getTxnManager();
		var lockManager = txnManager.lockManager();
		List<Txn> heldReaders = new ArrayList<>();
		AtomicReference<Throwable> failure = new AtomicReference<>();
		Thread reader = new Thread(() -> {
			try (RecordIterator ignored = valueStore.getTripleTerms(rangeSearch ? subjectId : -1, -1, -1)) {
				Assert.fail("Iterator construction should be interrupted while waiting for the read lock");
			} catch (Throwable t) {
				failure.set(t);
			}
		}, "interrupted-triple-term-reader");
		long writeStamp = 0;
		try {
			// Leave exactly one permit for the constructor that will be interrupted.
			for (int i = 0; i < TxnManager.POOL_SIZE - 2; i++) {
				heldReaders.add(txnManager.createReadTxn());
			}
			writeStamp = lockManager.writeLock();
			reader.start();
			long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
			while (!lockManager.isReaderActive()) {
				assertTrue("Iterator constructor should reach the read lock: " + failure.get(), reader.isAlive());
				assertTrue("Iterator constructor should reach the read lock", System.nanoTime() < deadline);
				Thread.onSpinWait();
			}
			reader.interrupt();
			reader.join(TimeUnit.SECONDS.toMillis(5));
			assertFalse("Interrupted iterator constructor should terminate", reader.isAlive());
			SailException exception = assertInstanceOf(SailException.class, failure.get());
			assertInstanceOf(InterruptedException.class, exception.getCause());
			lockManager.unlockWrite(writeStamp);
			writeStamp = 0;
			assertTimeoutPreemptively(Duration.ofSeconds(5), () -> {
				try (RecordIterator iterator = valueStore.getTripleTerms(rangeSearch ? subjectId : -1, -1, -1)) {
					assertNull(iterator.next());
				}
			}, "Failed construction must return its reader permit for the next iterator");
		} finally {
			if (writeStamp != 0) {
				lockManager.unlockWrite(writeStamp);
			}
			reader.interrupt();
			reader.join(TimeUnit.SECONDS.toMillis(5));
			heldReaders.forEach(Txn::close);
		}
	}

	@Test
	public void testNextIdCorrectlyIncrements() throws Exception {
		valueStore.startTransaction(true);
		long lastId = 0;
		for (int i = 0; i < 10; i++) {
			lastId = valueStore.storeValue(Values.iri("some:iri" + i));
		}
		valueStore.commit();
		valueStore.close();
		valueStore = createValueStore();
		long id = valueStore.storeValue(Values.iri("some:new"));
		// value of the next ID should be one greater than the last ID stored before closing the store
		assertEquals(ValueIds.getValue(lastId) + 1, ValueIds.getValue(id));
		lastId = id;
		id = valueStore.storeValue(SimpleValueFactory.getInstance()
				.createTripleTerm(Values.iri("some:new"), Values.iri("some:new1"), Values.iri("some:new2")));
		assertEquals(ValueIds.getValue(lastId) + 3, ValueIds.getValue(id));
		lastId = id;
		valueStore.close();
		valueStore = createValueStore();
		id = valueStore.storeValue(Values.iri("some:new3"));
		// value of the next ID should be one greater than the last ID stored before closing the store
		assertEquals(ValueIds.getValue(lastId) + 1, ValueIds.getValue(id));
	}

	private long storeValueAndReopen(Value value, LmdbStoreConfig config) throws Exception {
		valueStore.close();
		valueStore = createValueStore(config);
		long id;
		valueStore.startTransaction(true);
		id = valueStore.storeValue(value);
		valueStore.commit();
		reopenValueStore(config);
		return id;
	}

	private QueryBindingSet row(String bindingName, Value value) {
		QueryBindingSet row = new QueryBindingSet();
		row.addBinding(bindingName, value);
		return row;
	}

	private CloseableIteration<BindingSet> bindingSets(BindingSet... rows) {
		return new CloseableIteration<>() {

			private int index;

			private boolean closed;

			@Override
			public boolean hasNext() {
				return !closed && index < rows.length;
			}

			@Override
			public BindingSet next() {
				if (!hasNext()) {
					throw new NoSuchElementException();
				}
				return rows[index++];
			}

			@Override
			public void close() {
				closed = true;
			}
		};
	}

	private static final class CountingValueStore extends ValueStore {

		private int readTransactionCount;

		private int batchCursorOpenCount;

		private int batchCursorSeekCount;

		private int batchCursorNextCount;

		private int batchKeyBufferWrapCount;

		private int batchValueBufferWrapCount;

		private int batchDataBufferSliceCount;

		private int nativeWriteTransactionCount;

		private CountingValueStore(File dir, LmdbStoreConfig config) throws IOException {
			super(dir, config);
		}

		@Override
		public void startTransaction(boolean resize) throws IOException {
			super.startTransaction(resize);
			nativeWriteTransactionCount++;
		}

		@Override
		<T> T readTransaction(long env, LmdbUtil.Transaction<T> transaction) throws IOException {
			readTransactionCount++;
			return super.readTransaction(env, transaction);
		}

		void onBatchResolveCursorOpened() {
			batchCursorOpenCount++;
		}

		void onBatchResolveCursorSeek() {
			batchCursorSeekCount++;
		}

		void onBatchResolveCursorNext() {
			batchCursorNextCount++;
		}

		@Override
		void onBatchResolveKeyBufferWrapped() {
			batchKeyBufferWrapCount++;
		}

		@Override
		void onBatchResolveValueBufferWrapped() {
			batchValueBufferWrapCount++;
		}

		@Override
		void onBatchResolveDataBufferSliced() {
			batchDataBufferSliceCount++;
		}

		private Value borrowedLookup;

		private Long borrowedLookupId;
	}

	private void invokeStoreValues(ValueStore store, Value[] values, long[] ids, int count) throws Exception {
		Method method;
		try {
			method = ValueStore.class.getDeclaredMethod("storeValues", Value[].class, long[].class, int.class);
		} catch (NoSuchMethodException e) {
			Assert.fail("Expected ValueStore.storeValues(Value[], long[], int) batch API");
			return;
		}
		method.setAccessible(true);
		method.invoke(store, new Object[] { values, ids, count });
	}

	private int[] sortedOrder(long[] ids) {
		int[] order = new int[ids.length];
		for (int i = 0; i < ids.length; i++) {
			order[i] = i;
		}
		for (int i = 1; i < order.length; i++) {
			int index = order[i];
			long id = ids[index];
			int j = i - 1;
			while (j >= 0 && ids[order[j]] > id) {
				order[j + 1] = order[j];
				j--;
			}
			order[j + 1] = index;
		}
		return order;
	}

	private void reopenValueStore(LmdbStoreConfig config) throws Exception {
		valueStore.close();
		valueStore = createValueStore(config);
	}

	private boolean isInitialized(Object value) throws Exception {
		Field initializedField = value.getClass().getDeclaredField("initialized");
		initializedField.setAccessible(true);
		return initializedField.getBoolean(value);
	}

	private <T> T getField(Object target, String fieldName, Class<T> fieldType) throws Exception {
		Field field = target.getClass().getDeclaredField(fieldName);
		field.setAccessible(true);
		return fieldType.cast(field.get(target));
	}

	private long getLongField(Object target, String fieldName) throws Exception {
		Field field = target.getClass().getDeclaredField(fieldName);
		field.setAccessible(true);
		return field.getLong(target);
	}

	private ReverseIdCache<RdfTermKey, Object> valueIdCache(ValueStore store) throws Exception {
		Field field = ValueStore.class.getDeclaredField("valueIDCache");
		field.setAccessible(true);
		return (ReverseIdCache<RdfTermKey, Object>) field.get(store);
	}

	private void invokeCloseInactiveReadTransactions(ValueStore store) throws Exception {
		var method = store.getClass().getDeclaredMethod("closeInactiveReadTransactions");
		method.setAccessible(true);
		method.invoke(store);
	}

