	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	public void testNestedLazyTripleChildrenKeepOriginalEpoch(boolean primeNewerCache) throws Exception {
		TripleTerm inner = Values.tripleTerm(Values.iri("urn:retained:subject"), Values.iri("urn:retained:predicate"),
				Values.literal("a retained nested literal"));
		TripleTerm outer = Values.tripleTerm(Values.bnode("retained-outer"), Values.iri("urn:retained:outer-predicate"),
				inner);
		valueStore.startTransaction(true);
		long outerId = valueStore.storeValue(outer);
		long unrelatedId = valueStore.storeValue(Values.bnode("nested-unrelated"));
		valueStore.commit();
		LmdbTripleTerm held = (LmdbTripleTerm) valueStore.getLazyValue(outerId);
		long originalRevisionId = held.getValueStoreRevision().getRevisionId();
		retireValues(Set.of(unrelatedId));
		RevisionCollection laterRevisionCollected = trackRevisionCollection(valueStore.getLazyValue(outerId));
		retireValues(Set.of(outerId));
		if (primeNewerCache) {
			valueStore.getValue(outerId);
		}
		LmdbTripleTerm child = (LmdbTripleTerm) held.getObject();
		assertEquals("A deferred nested child must inherit its parent's original lifetime", originalRevisionId,
				child.getValueStoreRevision().getRevisionId());
		awaitRevisionCollection(laterRevisionCollected);
		evictRetiredValues();
		LmdbValue leaf = (LmdbValue) child.getObject();
		assertEquals("A deferred grandchild must retain the original lifetime", originalRevisionId,
				leaf.getValueStoreRevision().getRevisionId());
		assertEquals("a retained nested literal", leaf.stringValue());
		assertEquals(inner, child);
		Reference.reachabilityFence(held);
	}

