	@Test
	public void testSharedLazyGetterDuringShutdownDoesNotStrandClose() throws Exception {
		valueStore.close();
		CountDownLatch shutdownEntered = new CountDownLatch(1);
		CountDownLatch getterEntered = new CountDownLatch(1);
		AtomicReference<Thread> getterThread = new AtomicReference<>();
		valueStore = new ValueStore(new File(dataDir, "values"), new LmdbStoreConfig()) {

			@Override
			void endTransaction(boolean commit, boolean autoGrow) throws IOException {
				super.endTransaction(commit, autoGrow);
				if (!commit) {
					shutdownEntered.countDown();
					try {
						assertTrue("The getter must start inside the shutdown barrier",
								getterEntered.await(10, TimeUnit.SECONDS));
					} catch (InterruptedException e) {
						Thread.currentThread().interrupt();
						throw new IOException(e);
					}
				}
			}

			@Override
			boolean resolveValue(long id, LmdbValue value, ValueStoreRevision revision) {
				if (Thread.currentThread() == getterThread.get()) {
					getterEntered.countDown();
				}
				return super.resolveValue(id, value, revision);
			}
		};
		TripleTerm original = Values.tripleTerm(Values.bnode("concurrent-close-subject"), RDF.TYPE,
				Values.literal("concurrent close retained literal"));
		valueStore.startTransaction(true);
		long id = valueStore.storeValue(original);
		valueStore.commit();
		LmdbTripleTerm held = (LmdbTripleTerm) valueStore.getLazyValue(id);
		ExecutorService executor = Executors.newFixedThreadPool(2);
		try {
			Future<?> close = executor.submit(() -> {
				valueStore.close();
				return null;
			});
			assertTrue("Close must acquire its native barrier", shutdownEntered.await(10, TimeUnit.SECONDS));
			Future<Value> getter = executor.submit(() -> {
				getterThread.set(Thread.currentThread());
				return held.getObject();
			});
			close.get(10, TimeUnit.SECONDS);
			try {
				assertEquals(original.getObject(), getter.get(10, TimeUnit.SECONDS));
			} catch (ExecutionException e) {
				assertInstanceOf(SailException.class, e.getCause());
			}
			assertEquals(original, held);
		} finally {
			executor.shutdownNow();
			assertTrue("Neither a value monitor nor the native barrier may strand shutdown",
					executor.awaitTermination(10, TimeUnit.SECONDS));
		}
	}

	@Test
	public void testSharedLazyMaterializationFailureSuppressesNativeCloseFailureAndReopens() throws Exception {
		valueStore.close();
		AtomicBoolean shutdownArmed = new AtomicBoolean();
		AtomicBoolean firstResolution = new AtomicBoolean(true);
		AtomicReference<LmdbValue> failedValue = new AtomicReference<>();
		AtomicInteger environmentsClosed = new AtomicInteger();
		valueStore = new ValueStore(new File(dataDir, "values"), new LmdbStoreConfig()) {

			@Override
			boolean resolveValue(long id, LmdbValue value, ValueStoreRevision revision) {
				if (shutdownArmed.get() && firstResolution.compareAndSet(true, false)) {
					failedValue.set(value);
					throw new SailException("injected lazy materialization failure");
				}
				return super.resolveValue(id, value, revision);
			}

			@Override
			void closeEnvironment(long environment) {
				environmentsClosed.incrementAndGet();
				super.closeEnvironment(environment);
				throw new IllegalStateException("injected native close failure");
			}
		};
		long[] ids = storeBNodes("first-cleanup-value", "second-cleanup-value");
		LmdbValue first = valueStore.getLazyValue(ids[0]);
		LmdbValue second = valueStore.getLazyValue(ids[1]);
		shutdownArmed.set(true);
		SailException failure = assertThrows(SailException.class, () -> valueStore.close());
		assertEquals("injected lazy materialization failure", failure.getMessage());
		assertEquals("The later native failure must be retained", 1, failure.getSuppressed().length);
		assertEquals("injected native close failure", failure.getSuppressed()[0].getMessage());
		assertEquals("Native teardown must still run once", 1, environmentsClosed.get());
		LmdbValue successful = failedValue.get() == first ? second : first;
		assertEquals(failedValue.get() == first ? "second-cleanup-value" : "first-cleanup-value",
				successful.stringValue());
		valueStore.close();
		valueStore = createValueStore();
		assertEquals("first-cleanup-value", valueStore.getValue(ids[0]).stringValue());
		assertEquals("second-cleanup-value", valueStore.getValue(ids[1]).stringValue());
	}

