	@Test
	public void testDirectCloseWaitsForWriterAdmissionMaintenance() throws Exception {
		valueStore.close();
		CountDownLatch maintenanceEntered = new CountDownLatch(1);
		CountDownLatch releaseMaintenance = new CountDownLatch(1);
		CountDownLatch closeStarted = new CountDownLatch(1);
		CountDownLatch nativeAbortStarted = new CountDownLatch(1);
		AtomicBoolean pauseMaintenance = new AtomicBoolean();
		AtomicInteger environmentsClosed = new AtomicInteger();
		valueStore = new ValueStore(new File(dataDir, "values"), new LmdbStoreConfig()) {

			@Override
			protected void freeUnusedIdsAndValues(MemoryStack stack, long txn, Set<Long> revisionIds)
					throws IOException {
				if (pauseMaintenance.get()) {
					maintenanceEntered.countDown();
					try {
						assertTrue("The test must release writer-admission maintenance",
								releaseMaintenance.await(10, TimeUnit.SECONDS));
					} catch (InterruptedException e) {
						Thread.currentThread().interrupt();
						throw new IOException(e);
					}
					if (nativeAbortStarted.getCount() == 0 || environmentsClosed.get() != 0) {
						// Preserve a safe automated reproduction without dereferencing an already-freed native handle.
						throw new IOException("Native writer was aborted before admission maintenance completed");
					}
				}
				synchronized (this) {
					super.freeUnusedIdsAndValues(stack, txn, revisionIds);
				}
			}

			@Override
			void abortWriteTransaction(long transaction) {
				if (pauseMaintenance.get()) {
					nativeAbortStarted.countDown();
				}
				super.abortWriteTransaction(transaction);
			}

			@Override
			void closeEnvironment(long environment) {
				environmentsClosed.incrementAndGet();
				super.closeEnvironment(environment);
			}
		};
		long id = storeBNodes("admission-maintenance-retired")[0];
		RevisionCollection collected = trackRevisionCollection(valueStore.getLazyValue(id));
		retireValues(Set.of(id));
		awaitReclamationEligibility(collected);
		valueStore.forceEvictionOfValues();
		pauseMaintenance.set(true);
		ExecutorService executor = Executors.newFixedThreadPool(2);
		Future<?> starter = null;
		Future<?> closer = null;
		try {
			starter = executor.submit(() -> {
				valueStore.startTransaction(true);
				return null;
			});
			assertTrue("A real retirement cohort must enter native admission maintenance",
					maintenanceEntered.await(5, TimeUnit.SECONDS));
			closer = executor.submit(() -> {
				closeStarted.countDown();
				valueStore.close();
				return null;
			});
			assertTrue(closeStarted.await(5, TimeUnit.SECONDS));
			assertFalse("Close must not abort a native writer while its admission maintenance is active",
					nativeAbortStarted.await(150, TimeUnit.MILLISECONDS));
			assertEquals("The environment must remain live until native admission maintenance finishes", 0,
					environmentsClosed.get());
			releaseMaintenance.countDown();
			starter.get(5, TimeUnit.SECONDS);
			closer.get(5, TimeUnit.SECONDS);
			assertEquals(1, environmentsClosed.get());
		} finally {
			releaseMaintenance.countDown();
			if (starter != null) {
				try {
					starter.get(5, TimeUnit.SECONDS);
				} catch (ExecutionException failure) {
					assertInstanceOf(IOException.class, failure.getCause());
					assertEquals("Native writer was aborted before admission maintenance completed",
							failure.getCause().getMessage());
				}
			}
			if (closer != null) {
				closer.get(5, TimeUnit.SECONDS);
			}
			executor.shutdownNow();
			assertTrue(executor.awaitTermination(5, TimeUnit.SECONDS));
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	public void testWriterAdmissionCompletionAndFailureAllowClear(boolean failMaintenance) throws Exception {
		valueStore.close();
		CountDownLatch maintenanceEntered = new CountDownLatch(1);
		CountDownLatch releaseMaintenance = new CountDownLatch(1);
		CountDownLatch clearStarted = new CountDownLatch(1);
		AtomicBoolean armed = new AtomicBoolean();
		valueStore = new ValueStore(new File(dataDir, "values"), new LmdbStoreConfig()) {

			@Override
			protected void freeUnusedIdsAndValues(MemoryStack stack, long txn, Set<Long> revisionIds)
					throws IOException {
				if (armed.get()) {
					maintenanceEntered.countDown();
					try {
						assertTrue(releaseMaintenance.await(10, TimeUnit.SECONDS));
					} catch (InterruptedException e) {
						Thread.currentThread().interrupt();
						throw new IOException(e);
					}
				}
				synchronized (this) {
					if (armed.get() && failMaintenance) {
						throw new IOException("injected admission maintenance failure");
					}
					super.freeUnusedIdsAndValues(stack, txn, revisionIds);
				}
			}
		};
		long id = storeBNodes("clear-admission-retired")[0];
		RevisionCollection collected = trackRevisionCollection(valueStore.getLazyValue(id));
		retireValues(Set.of(id));
		awaitReclamationEligibility(collected);
		valueStore.forceEvictionOfValues();
		armed.set(true);
		ExecutorService executor = Executors.newFixedThreadPool(2);
		try {
			Future<?> starter = executor.submit(() -> {
				valueStore.startTransaction(true);
				return null;
			});
			assertTrue(maintenanceEntered.await(5, TimeUnit.SECONDS));
			Future<?> clear = executor.submit(() -> {
				clearStarted.countDown();
				valueStore.clear();
				return null;
			});
			assertTrue(clearStarted.await(5, TimeUnit.SECONDS));
			assertThrows(TimeoutException.class, () -> clear.get(150, TimeUnit.MILLISECONDS),
					"Clear must wait for admission maintenance before taking the store monitor");
			releaseMaintenance.countDown();
			if (failMaintenance) {
				ExecutionException failure = assertThrows(ExecutionException.class,
						() -> starter.get(5, TimeUnit.SECONDS));
				assertInstanceOf(IOException.class, failure.getCause());
				assertEquals("injected admission maintenance failure", failure.getCause().getMessage());
			} else {
				starter.get(5, TimeUnit.SECONDS);
			}
			clear.get(5, TimeUnit.SECONDS);
			armed.set(false);
			long freshId = storeBNodes("reopened-after-admission")[0];
			assertEquals("reopened-after-admission", valueStore.getValue(freshId).stringValue());
		} finally {
			releaseMaintenance.countDown();
			executor.shutdownNow();
			assertTrue(executor.awaitTermination(5, TimeUnit.SECONDS));
		}
	}

