	/** An isolated native owner keeps a reproduced noninterruptible lock cycle out of the Surefire process. */

	/**
	 * An isolated native owner keeps a reproduced noninterruptible lock cycle out of the Surefire process.
	 */
	public static final class WriterRevisionCheckpointScenario {

		public static void main(String[] arguments) throws Exception {
			LmdbStoreConfig config = new LmdbStoreConfig().setValueDBSize(1024L * 1024)
					.setAutoGrow(true)
					.setInlineLiterals(false);
			CountDownLatch checkpointEntered = new CountDownLatch(1);
			AtomicBoolean completed = new AtomicBoolean();
			Thread writer = Thread.currentThread();
			Thread diagnostic = Thread.ofPlatform().daemon().unstarted(() -> {
				try {
					if (!checkpointEntered.await(15, TimeUnit.SECONDS)) {
						return;
					}
					ThreadMXBean threads = ManagementFactory.getThreadMXBean();
					long fixtureDeadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(15);
					while (!completed.get() && System.nanoTime() < fixtureDeadline) {
						ThreadInfo state = threads.getThreadInfo(writer.threadId(), Integer.MAX_VALUE);
						if (state != null && state.getThreadState() == Thread.State.WAITING) {
							boolean inGetId = false;
							boolean inCheckpoint = false;
							boolean inRevisionWriteLock = false;
							for (StackTraceElement frame : state.getStackTrace()) {
								if (frame.getClassName().equals(ValueStore.class.getName())) {
									inGetId |= frame.getMethodName().equals("getId");
									inCheckpoint |= frame.getMethodName().equals("endTransaction");
								} else if (frame.getClassName().equals("java.util.concurrent.locks.StampedLock")) {
									inRevisionWriteLock |= frame.getMethodName().equals("writeLock");
								}
							}
							if (inGetId && inCheckpoint && inRevisionWriteLock) {
								System.out.println("RECLAMATION_CHECKPOINT_REVISION_UPGRADE_BLOCKED");
								for (StackTraceElement frame : state.getStackTrace()) {
									System.out.println("\tat " + frame);
								}
								System.out.flush();
								return;
							}
						}
						Thread.yield();
					}
				} catch (InterruptedException failure) {
					Thread.currentThread().interrupt();
				}
			});
			ValueStore store = new ValueStore(Path.of(arguments[0]).toFile(), config);
			try {
				store.startTransaction(true);
				long retiredId = store.storeValue(Values.bnode("revision-checkpoint-retired"));
				store.commit();
				store.startTransaction(true);
				store.gcIds(Set.of(retiredId), new HashSet<>());
				store.setResizeCheckpointListener(checkpointEntered::countDown);
				diagnostic.start();
				String label = "revision-checkpoint".repeat(150_000);
				long largeId = store.storeValue(Values.literal(label));
				store.commit();
				assertEquals("The actual resized dictionary must contain the complete value", label,
						store.getValue(largeId).stringValue());
				assertEquals("A native allocation checkpoint must have occurred", 0L, checkpointEntered.getCount());
				completed.set(true);
				System.out.println("RECLAMATION_CHECKPOINT_COMPLETED");
			} finally {
				store.close();
			}
		}
	}

	/** Uses a real value-map growth checkpoint to expose association-gate/native-reader barrier lock ordering. */
	public static final class AssociationNativeBarrierResizeScenario {
		private static final long OBSERVATION_TIMEOUT_NANOS = TimeUnit.SECONDS.toNanos(8);

		public static void main(String[] arguments) throws Exception {
			LmdbStoreConfig config = new LmdbStoreConfig().setValueDBSize(1024L * 1024)
					.setAutoGrow(true)
					.setInlineLiterals(false);
			CountDownLatch checkpointEntered = new CountDownLatch(1);
			CountDownLatch continueResize = new CountDownLatch(1);
			AtomicReference<Thread> readerThread = new AtomicReference<>();
			AtomicReference<String> readerValue = new AtomicReference<>();
			AtomicReference<Throwable> readerFailure = new AtomicReference<>();
			AtomicReference<Throwable> monitorFailure = new AtomicReference<>();
			AtomicBoolean readerCompleted = new AtomicBoolean();
			AtomicBoolean cycleDetected = new AtomicBoolean();
			AtomicReference<Long> initialId = new AtomicReference<>();
			Thread writerThread = Thread.currentThread();
			ValueStore store = new ValueStore(Path.of(arguments[0]).toFile(), config);
			Thread monitor = Thread.ofPlatform().daemon().name("association-native-barrier-monitor").unstarted(() -> {
				try {
					if (!checkpointEntered.await(10, TimeUnit.SECONDS)) {
						System.out.println("ASSOCIATION_NATIVE_BARRIER_CHECKPOINT_NOT_REACHED");
						return;
					}
					printThread("ASSOCIATION_NATIVE_BARRIER_WRITER_AT_CHECKPOINT", writerThread);
					Thread reader = Thread.ofPlatform().name("association-native-barrier-reader").unstarted(() -> {
						try {
							readerValue.set(store.getValue(initialId.get()).stringValue());
						} catch (Throwable failure) {
							readerFailure.set(failure);
						} finally {
							readerCompleted.set(true);
						}
					});
					readerThread.set(reader);
					reader.start();
					long deadline = System.nanoTime() + OBSERVATION_TIMEOUT_NANOS;
					boolean admissionBoundaryObserved = false;
					while (!readerCompleted.get() && System.nanoTime() < deadline) {
						ThreadInfo state = threadInfo(reader);
						boolean unsafeNativeAdmission = state != null
								&& state.getLockOwnerId() == writerThread.threadId()
								&& hasFrame(state, ValueStore.class.getName(), "acquireAssociationGate")
								&& hasFrame(state, ValueStore.class.getName() + "$ValueReadScope", "open")
								&& hasFrame(state, TxnManager.class.getName(), "doWithScoped");
						boolean safeOutOfLockAdmission = state != null
								&& state.getLockOwnerId() == writerThread.threadId()
								&& hasFrame(state, ValueStore.class.getName(), "awaitValueReaderAdmission")
								&& hasFrame(state, ValueStore.class.getName(), "acquireAssociationGate");
						if (unsafeNativeAdmission || safeOutOfLockAdmission) {
							admissionBoundaryObserved = true;
							System.out.println("ASSOCIATION_NATIVE_BARRIER_READER_ADMISSION_BOUNDARY "
									+ (unsafeNativeAdmission ? "unsafe-native-scope" : "safe-out-of-lock"));
							printThread("ASSOCIATION_NATIVE_BARRIER_READER_WAITING_FOR_GATE", reader);
							break;
						}
						Thread.yield();
					}
					if (!admissionBoundaryObserved) {
						throw new IOException(
								"The reader did not reach either actual association-gate admission boundary");
					}
					continueResize.countDown();
					deadline = System.nanoTime() + OBSERVATION_TIMEOUT_NANOS;
					while (!readerCompleted.get() && System.nanoTime() < deadline) {
						ThreadInfo readerState = threadInfo(reader);
						ThreadInfo writerState = threadInfo(writerThread);
						boolean readerWaitingForGate = readerState != null
								&& readerState.getLockOwnerId() == writerThread.threadId()
								&& hasFrame(readerState, ValueStore.class.getName(), "acquireAssociationGate")
								&& hasFrame(readerState, ValueStore.class.getName() + "$ValueReadScope", "open")
								&& hasFrame(readerState, TxnManager.class.getName(), "doWithScoped");
						boolean readerHoldsNativeReadBarrier = hasFrame(readerState, TxnManager.class.getName(),
								"startScopedReadTxn")
								&& hasFrame(readerState, ValueStore.class.getName() + "$ValueReadScope", "open")
								&& hasFrame(readerState, TxnManager.class.getName(), "doWithScoped");
						boolean writerWaitingForBarrier = hasFrame(writerState,
								"org.eclipse.rdf4j.common.concurrent.locks.StampedLongAdderLockManager", "writeLock")
								&& hasFrame(writerState, ValueStore.class.getName(), "resizeMapInternal");
						if (readerWaitingForGate && readerHoldsNativeReadBarrier && writerWaitingForBarrier) {
							cycleDetected.set(true);
							System.out.println("ASSOCIATION_NATIVE_BARRIER_CYCLE");
							System.out.println("ASSOCIATION_NATIVE_BARRIER_READER_HOLDS_NATIVE_READ_BARRIER");
							printThread("ASSOCIATION_NATIVE_BARRIER_WRITER_WAITING_FOR_READERS", writerThread);
							printThread("ASSOCIATION_NATIVE_BARRIER_READER_WAITING_FOR_GATE", reader);
							reader.interrupt();
							break;
						}
						Thread.yield();
					}
				} catch (Throwable failure) {
					monitorFailure.set(failure);
				} finally {
					continueResize.countDown();
				}
			});
			try {
				store.startTransaction(true);
				initialId.set(store.storeValue(Values.literal("committed reader value")));
				store.commit();
				long initialMapSize = store.mapSizeBytes();
				long initialMapGeneration = store.nativeMapGeneration();
				store.setResizeCheckpointListener(() -> {
					System.out.println("ASSOCIATION_NATIVE_BARRIER_RESIZE_CHECKPOINT");
					checkpointEntered.countDown();
					try {
						if (!continueResize.await(15, TimeUnit.SECONDS)) {
							throw new IllegalStateException("Timed out waiting for the resize lock-order observation");
						}
					} catch (InterruptedException interrupted) {
						Thread.currentThread().interrupt();
						throw new IllegalStateException("Interrupted while waiting at the resize checkpoint",
								interrupted);
					}
				});
				monitor.start();
				store.startTransaction(true);
				String label = "native association resize ".repeat(Math.toIntExact(initialMapSize / 4));
				long largeId = store.storeValue(Values.literal(label));
				store.commit();
				assertEquals("the allocation must preserve the complete value across resize", label,
						store.getValue(largeId).stringValue());
				long grownMapSize = store.mapSizeBytes();
				long grownMapGeneration = store.nativeMapGeneration();
				assertTrue("the real allocation must grow the value map from " + initialMapSize + " bytes to "
						+ grownMapSize, grownMapSize > initialMapSize);
				assertTrue("the real allocation must advance the native map generation from " + initialMapGeneration
						+ " to " + grownMapGeneration, grownMapGeneration > initialMapGeneration);
				System.out.println("ASSOCIATION_NATIVE_BARRIER_MAP_GROWTH map=" + initialMapSize + "->" + grownMapSize
						+ ", generation=" + initialMapGeneration + "->" + grownMapGeneration + ", valueLength="
						+ label.length());
				monitor.join(TimeUnit.SECONDS.toMillis(12));
				if (monitor.isAlive()) {
					throw new IOException("The association/native-barrier monitor did not finish");
				}
				Thread reader = readerThread.get();
				if (reader != null) {
					reader.join(TimeUnit.SECONDS.toMillis(5));
					if (reader.isAlive()) {
						throw new IOException("The committed-value reader did not terminate");
					}
				}
				if (monitorFailure.get() != null) {
					throw new IOException("The association/native-barrier monitor failed", monitorFailure.get());
				}
				if (readerCompleted.get() && readerFailure.get() == null) {
					assertEquals("the concurrently read committed value must remain intact", "committed reader value",
							readerValue.get());
					System.out.println("ASSOCIATION_NATIVE_BARRIER_READER_COMPLETED");
				} else if (cycleDetected.get()) {
					assertEquals("the committed value must remain readable after releasing the lock cycle",
							"committed reader value", store.getValue(initialId.get()).stringValue());
					System.out.println("ASSOCIATION_NATIVE_BARRIER_COMMITTED_VALUE_REMAINS_READABLE");
					System.out.println("ASSOCIATION_NATIVE_BARRIER_READER_INTERRUPTED_TO_RELEASE_CYCLE");
				} else {
					throw new IOException("The concurrent committed-value reader did not complete",
							readerFailure.get());
				}
				System.out.println("ASSOCIATION_NATIVE_BARRIER_RESIZE_COMPLETED");
			} finally {
				continueResize.countDown();
				Thread reader = readerThread.get();
				if (reader != null && reader.isAlive()) {
					reader.interrupt();
					reader.join(TimeUnit.SECONDS.toMillis(5));
				}
				monitor.interrupt();
				monitor.join(TimeUnit.SECONDS.toMillis(5));
				store.close();
			}
		}

		private static ThreadInfo threadInfo(Thread thread) {
			return ManagementFactory.getThreadMXBean().getThreadInfo(thread.threadId(), Integer.MAX_VALUE);
		}

		private static boolean hasFrame(ThreadInfo thread, String className, String methodName) {
			if (thread == null) {
				return false;
			}
			for (StackTraceElement frame : thread.getStackTrace()) {
				if (frame.getClassName().equals(className) && frame.getMethodName().equals(methodName)) {
					return true;
				}
			}
			return false;
		}

		private static void printThread(String label, Thread thread) {
			ThreadInfo info = threadInfo(thread);
			if (info == null) {
				System.out.println(label + " unavailable");
				return;
			}
			System.out.println(label + " " + info.getThreadName() + " state=" + info.getThreadState() + " lock="
					+ info.getLockName() + " lockOwner=" + info.getLockOwnerName() + "#" + info.getLockOwnerId());
			for (StackTraceElement frame : info.getStackTrace()) {
				System.out.println("\tat " + frame);
			}
			System.out.flush();
		}
	}

	/** Proves close must release its native barrier before waiting on a borrowed writer's association gate. */
	public static final class CloseAssociationNativeBarrierResizeScenario {
		private static final long OBSERVATION_TIMEOUT_NANOS = TimeUnit.SECONDS.toNanos(8);

		private final Path directory;
		private final LmdbStoreConfig config = new LmdbStoreConfig().setValueDBSize(1024L * 1024)
				.setAutoGrow(true)
				.setInlineLiterals(false);
		private final CountDownLatch checkpointEntered = new CountDownLatch(1);
		private final CountDownLatch continueResize = new CountDownLatch(1);
		private final AtomicReference<Thread> closerThread = new AtomicReference<>();
		private final AtomicReference<Throwable> closeFailure = new AtomicReference<>();
		private final AtomicReference<Throwable> writerFailure = new AtomicReference<>();
		private final AtomicReference<Throwable> monitorFailure = new AtomicReference<>();
		private final AtomicBoolean closeCompleted = new AtomicBoolean();
		private final AtomicBoolean writerCompleted = new AtomicBoolean();
		private final AtomicBoolean cycleDetected = new AtomicBoolean();
		private final Thread writerThread = Thread.currentThread();
		private final ValueStore store;
		private final Thread monitor = Thread.ofPlatform()
				.daemon()
				.name("close-association-native-barrier-monitor")
				.unstarted(this::monitorResize);

		private long initialId;
		private String label;

		public static void main(String[] arguments) throws Exception {
			new CloseAssociationNativeBarrierResizeScenario(Path.of(arguments[0])).run();
		}

		private CloseAssociationNativeBarrierResizeScenario(Path directory) throws IOException {
			this.directory = directory;
			store = new ValueStore(directory.toFile(), config);
		}

		private void run() throws Exception {
			try {
				store.startTransaction(true);
				initialId = store.storeValue(Values.literal("committed close baseline"));
				store.commit();
				long initialMapSize = store.mapSizeBytes();
				label = "native close association resize ".repeat(Math.toIntExact(initialMapSize / 4));
				store.setResizeCheckpointListener(() -> {
					System.out.println("CLOSE_ASSOCIATION_NATIVE_BARRIER_RESIZE_CHECKPOINT");
					checkpointEntered.countDown();
					try {
						if (!continueResize.await(15, TimeUnit.SECONDS)) {
							throw new IllegalStateException(
									"Timed out waiting for the close/resize lock-order observation");
						}
					} catch (InterruptedException interrupted) {
						Thread.currentThread().interrupt();
						throw new IllegalStateException("Interrupted while waiting at the close/resize checkpoint",
								interrupted);
					}
				});
				monitor.start();
				store.startTransaction(true);
				try {
					store.storeValue(Values.literal(label));
				} catch (Throwable failure) {
					writerFailure.set(failure);
				} finally {
					writerCompleted.set(true);
				}
				monitor.join(TimeUnit.SECONDS.toMillis(12));
				if (monitor.isAlive()) {
					throw new IOException("The close/resize monitor did not finish");
				}
				Thread closer = closerThread.get();
				if (closer == null) {
					throw new IOException("The close/resize monitor did not start the closer");
				}
				closer.join(TimeUnit.SECONDS.toMillis(10));
				if (closer.isAlive() || !closeCompleted.get()) {
					throw new IOException("The close/resize closer did not finish");
				}
				if (monitorFailure.get() != null) {
					throw new IOException("The close/resize monitor failed", monitorFailure.get());
				}
				if (closeFailure.get() != null) {
					throw new IOException("ValueStore.close must finish after the active resize settles",
							closeFailure.get());
				}
				System.out.println("CLOSE_ASSOCIATION_NATIVE_BARRIER_CLOSE_COMPLETED");
				Throwable resizeFailure = writerFailure.get();
				if (cycleDetected.get()) {
					if (!(resizeFailure instanceof IOException ioException
							&& ioException.getCause() instanceof InterruptedException)) {
						throw new IOException(
								"The captured cycle must be released only by the interrupted native-write wait",
								resizeFailure);
					}
					System.out.println("CLOSE_ASSOCIATION_NATIVE_BARRIER_WRITER_INTERRUPTED "
							+ ioExceptionText(resizeFailure));
				} else {
					if (!(resizeFailure instanceof IOException ioException
							&& "ValueStore is closed".equals(ioException.getMessage()))) {
						throw new IOException(
								"Close must reject the resize restart with IOException(\"ValueStore is closed\")",
								resizeFailure);
					}
					System.out.println("CLOSE_ASSOCIATION_NATIVE_BARRIER_WRITER_RESTART_REJECTED "
							+ ioExceptionText(resizeFailure));
				}

				ValueStore reopened = new ValueStore(directory.toFile(), config);
				try {
					assertEquals("the committed baseline must survive close and reopen", "committed close baseline",
							reopened.getValue(initialId).stringValue());
					assertEquals("the uncommitted value must not be published by concurrent close",
							LmdbValue.UNKNOWN_ID,
							reopened.getId(Values.literal(label), false));
					System.out.println("CLOSE_ASSOCIATION_NATIVE_BARRIER_REOPENED_BASELINE");
				} finally {
					reopened.close();
				}
			} finally {
				continueResize.countDown();
				monitor.interrupt();
				monitor.join(TimeUnit.SECONDS.toMillis(5));
			}
		}

		private void monitorResize() {
			try {
				if (!checkpointEntered.await(10, TimeUnit.SECONDS)) {
					System.out.println("CLOSE_ASSOCIATION_NATIVE_BARRIER_CHECKPOINT_NOT_REACHED");
					return;
				}
				printThread("CLOSE_ASSOCIATION_NATIVE_BARRIER_WRITER_AT_CHECKPOINT", writerThread);
				Thread closer = Thread.ofPlatform()
						.daemon()
						.name("close-association-native-barrier-closer")
						.unstarted(() -> {
							closerThread.set(Thread.currentThread());
							try {
								store.close();
							} catch (Throwable failure) {
								closeFailure.set(failure);
							} finally {
								closeCompleted.set(true);
							}
						});
				closer.start();
				long deadline = System.nanoTime() + OBSERVATION_TIMEOUT_NANOS;
				boolean closeFenceReady = false;
				while (System.nanoTime() < deadline) {
					ThreadInfo closerState = threadInfo(closer);
					boolean waitingForNativeBarrier = hasFrame(closerState, ValueStore.class.getName(),
							"closeUnderMonitor")
							&& hasFrame(closerState, TxnManager.class.getName(), "acquireCloseBarrier")
							&& hasFrame(closerState,
									"org.eclipse.rdf4j.common.concurrent.locks.StampedLongAdderLockManager",
									"writeLock");
					boolean waitingForHeldBarrierGate = closerState != null
							&& closerState.getLockOwnerId() == writerThread.threadId()
							&& hasFrame(closerState, ValueStore.class.getName(), "closeUnderMonitor")
							&& hasFrame(closerState, ValueStore.class.getName(), "endWriterTransaction")
							&& hasFrame(closerState, "java.util.concurrent.locks.ReentrantLock", "lock");
					boolean waitingOutsideBarrier = closerState != null
							&& closerState.getThreadState() == Thread.State.WAITING
							&& closerState.getLockOwnerId() == writerThread.threadId()
							&& hasFrame(closerState, ValueStore.class.getName(), "awaitWriterStartsForShutdown")
							&& hasFrame(closerState, "java.util.concurrent.locks.ReentrantLock", "lock")
							&& !hasFrame(closerState, ValueStore.class.getName(), "closeUnderMonitor")
							&& !hasFrame(closerState, TxnManager.class.getName(), "acquireCloseBarrier");
					if (waitingForNativeBarrier || waitingForHeldBarrierGate || waitingOutsideBarrier) {
						closeFenceReady = true;
						System.out.println("CLOSE_ASSOCIATION_NATIVE_BARRIER_CLOSE_FENCE_READY "
								+ (waitingForNativeBarrier ? "native-barrier"
										: waitingForHeldBarrierGate ? "unsafe-held-barrier-gate"
												: "safe-out-of-lock-admission"));
						printThread("CLOSE_ASSOCIATION_NATIVE_BARRIER_CLOSER_AT_FENCE", closer);
						break;
					}
					Thread.yield();
				}
				if (!closeFenceReady) {
					System.out.println("CLOSE_ASSOCIATION_NATIVE_BARRIER_CLOSE_FENCE_NOT_OBSERVED");
					printThread("CLOSE_ASSOCIATION_NATIVE_BARRIER_CLOSER_NOT_READY", closer);
					throw new AssertionError("The close/resize schedule did not reach a safe or unsafe close fence");
				}
				continueResize.countDown();
				deadline = System.nanoTime() + OBSERVATION_TIMEOUT_NANOS;
				while (System.nanoTime() < deadline) {
					ThreadInfo closerState = threadInfo(closer);
					ThreadInfo writerState = threadInfo(writerThread);
					boolean closerWaitingForGate = closerState != null
							&& closerState.getLockOwnerId() == writerThread.threadId()
							&& hasFrame(closerState, ValueStore.class.getName(), "closeUnderMonitor")
							&& hasFrame(closerState, ValueStore.class.getName(), "endWriterTransaction")
							&& hasFrame(closerState, "java.util.concurrent.locks.ReentrantLock", "lock");
					boolean writerWaitingForBarrier = hasFrame(writerState,
							"org.eclipse.rdf4j.common.concurrent.locks.StampedLongAdderLockManager", "writeLock")
							&& hasFrame(writerState, TxnManager.class.getName() + "$NativeBarrier", "writeLock")
							&& hasFrame(writerState, ValueStore.class.getName(), "resizeMapInternal");
					if (closerWaitingForGate && writerWaitingForBarrier) {
						cycleDetected.set(true);
						System.out.println("CLOSE_ASSOCIATION_NATIVE_BARRIER_CYCLE");
						printThread("CLOSE_ASSOCIATION_NATIVE_BARRIER_CLOSER_WAITING_FOR_GATE", closer);
						printThread("CLOSE_ASSOCIATION_NATIVE_BARRIER_WRITER_WAITING_FOR_NATIVE_WRITE", writerThread);
						writerThread.interrupt();
						break;
					}
					if (writerCompleted.get() && closeCompleted.get()) {
						System.out.println("CLOSE_ASSOCIATION_NATIVE_BARRIER_THREADS_SETTLED");
						break;
					}
					Thread.yield();
				}
				if (!cycleDetected.get() && !(writerCompleted.get() && closeCompleted.get())) {
					System.out.println("CLOSE_ASSOCIATION_NATIVE_BARRIER_SETTLEMENT_NOT_OBSERVED");
					printThread("CLOSE_ASSOCIATION_NATIVE_BARRIER_CLOSER_AT_TIMEOUT", closer);
					printThread("CLOSE_ASSOCIATION_NATIVE_BARRIER_WRITER_AT_TIMEOUT", writerThread);
				}
			} catch (Throwable failure) {
				monitorFailure.set(failure);
			} finally {
				continueResize.countDown();
			}
		}

		private static ThreadInfo threadInfo(Thread thread) {
			return ManagementFactory.getThreadMXBean().getThreadInfo(thread.threadId(), Integer.MAX_VALUE);
		}

		private static boolean hasFrame(ThreadInfo thread, String className, String methodName) {
			if (thread == null) {
				return false;
			}
			for (StackTraceElement frame : thread.getStackTrace()) {
				if (frame.getClassName().equals(className) && frame.getMethodName().equals(methodName)) {
					return true;
				}
			}
			return false;
		}

		private static void printThread(String label, Thread thread) {
			ThreadInfo info = threadInfo(thread);
			if (info == null) {
				System.out.println(label + " unavailable");
				return;
			}
			System.out.println(label + " " + info.getThreadName() + " state=" + info.getThreadState() + " lock="
					+ info.getLockName() + " lockOwner=" + info.getLockOwnerName() + "#" + info.getLockOwnerId());
			for (StackTraceElement frame : info.getStackTrace()) {
				System.out.println("\tat " + frame);
			}
			System.out.flush();
		}

		private static String ioExceptionText(Throwable failure) {
			return failure.getClass().getName() + ": " + failure.getMessage() + " caused by " + failure.getCause();
		}
	}

	private long[] storeBNodes(String... labels) throws IOException {
		long[] ids = new long[labels.length];
		valueStore.startTransaction(true);
		for (int i = 0; i < labels.length; i++) {
			ids[i] = valueStore.storeValue(Values.bnode(labels[i]));
		}
		valueStore.commit();
		return ids;
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	public void testLazyBorrowDoesNotReadReusedIdFromOlderDictionary(boolean rollback) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig();
		try (TripleStore triples = new TripleStore(new File(dataDir, "borrow-reused-id-triples"), config, valueStore)) {
			long id = storeBNodes("borrow-retired-old-value")[0];
			RevisionCollection collected = trackRevisionCollection(valueStore.getLazyValue(id));
			retireValues(Set.of(id));
			try (TxnManager.ReaderReservation oldTripleReservation = triples.getTxnManager().reserveReadTxn(false);
					Txn oldTripleTxn = oldTripleReservation.startPinned(triples::getDataRevision);
					ValueStore.ReadSnapshotReservation oldReservation = valueStore.reserveReadSnapshot();
					ValueStore.ReadSnapshot oldSnapshot = oldReservation.start(oldTripleTxn)) {
				// This paired view opens after reverse-map retirement, but its dictionary still contains the
				// old ID-to-value association while the earlier Lazy retention cohort awaits reclamation.
				oldSnapshot.retainStableIds(oldTripleTxn);
				awaitReclamationEligibility(collected);
				evictRetiredValues();
				long replacementId = storeBNodes("borrow-reused-new-value")[0];
				assertEquals("Native reclamation must actually reuse the retired ID", id, replacementId);
				if (rollback) {
					valueStore.startTransaction(true);
					valueStore.rollback();
				}
				LmdbValue escaped;
				try (TxnManager.ReaderReservation newTripleReservation = triples.getTxnManager().reserveReadTxn(false);
						Txn newTripleTxn = newTripleReservation.startPinned(triples::getDataRevision);
						ValueStore.ReadSnapshotReservation newReservation = valueStore.reserveReadSnapshot();
						ValueStore.ReadSnapshot newSnapshot = newReservation.start(newTripleTxn)) {
					newSnapshot.retainStableIds(newTripleTxn);
					escaped = valueStore.getLazyValue(newSnapshot, replacementId);
					assertFalse("The preferred newer view must close before the value resolves",
							isInitialized(escaped));
				}
				assertEquals("An older native dictionary containing this ID must not supply its retired meaning",
						"borrow-reused-new-value", escaped.stringValue());
			}
		}
	}

	@Test
	public void testLateValueCompletionDoesNotRestoreRetiredCacheAssociation() throws Exception {
		valueStore.close();
		valueStore = createValueStore(hashCacheEnabledConfig());
		long id = storeBNodes("late-completion-original")[0];
		LmdbValue original = valueStore.getLazyValue(id);
		RevisionCollection collected = trackRevisionCollection(original);
		original.init();
		ValueStoreRevision originalRevision = original.getValueStoreRevision();
		retireValues(Set.of(id));
		awaitReclamationEligibility(collected);
		evictRetiredValues();
		assertEquals(id, storeBNodes("late-completion-replacement")[0]);
		for (int i = 0; i < 3; i++) {
			valueStore.startTransaction(true);
			valueStore.rollback();
		}
		// A completion admitted before retirement can arrive after cache clearing. Consumers must validate
		// their epoch even when the ready value is correctly release-published into the reused cache slot.
		originalRevision.valueInitialized(id, original);
		Value expected = Values.bnode("late-completion-replacement");
		assertEquals("Direct reads must reject an obsolete completed cache entry", expected, valueStore.getValue(id));
		assertEquals("Lazy reads must reject the same obsolete association", expected, valueStore.getLazyValue(id));
		assertEquals(expected.hashCode(), valueStore.getLazyValue(id).hashCode());
		assertEquals("The old escaped ready value keeps its lexical meaning after ID reuse",
				Values.bnode("late-completion-original"), original);
		assertEquals(Values.bnode("late-completion-original").hashCode(), original.hashCode());
	}

	@ParameterizedTest
	@ValueSource(strings = { "getStoredHash", "storeHash" })
	public void testStoredHashAccessCannotCrossNativeIdReassignment(String hashOperation) throws Exception {
		valueStore.close();
		CountDownLatch revisionCaptured = new CountDownLatch(1);
		CountDownLatch releaseHashAccess = new CountDownLatch(1);
		AtomicReference<Thread> hashThread = new AtomicReference<>();
		AtomicBoolean pauseHash = new AtomicBoolean();
		valueStore = new ValueStore(new File(dataDir, "values"), hashCacheEnabledConfig()) {

			@Override
			int getStoredHash(long id, long revisionId) {
				pauseAtHashAccess("getStoredHash");
				return super.getStoredHash(id, revisionId);
			}

			@Override
			void storeHash(long id, int hash, long revisionId) {
				pauseAtHashAccess("storeHash");
				super.storeHash(id, hash, revisionId);
			}

			private void pauseAtHashAccess(String operation) {
				if (hashOperation.equals(operation) && Thread.currentThread() == hashThread.get()
						&& pauseHash.compareAndSet(true, false)) {
					revisionCaptured.countDown();
					try {
						assertTrue("The test must release the captured hash revision",
								releaseHashAccess.await(10, TimeUnit.SECONDS));
					} catch (InterruptedException e) {
						Thread.currentThread().interrupt();
						throw new SailException(e);
					}
				}
			}
		};
		Value original = Values.bnode("hash-association-original");
		Value replacement = Values.bnode("hash-association-replacement");
		int originalHash = original.hashCode();
		int replacementHash = replacement.hashCode();
		assertNotEquals("The real values must have distinct hash codes", originalHash, replacementHash);
		assertNotEquals(0, originalHash);
		assertNotEquals(0, replacementHash);
		long id = storeBNodes("hash-association-original")[0];
		LmdbValue ready = valueStore.getLazyValue(id);
		RevisionCollection collected = trackRevisionCollection(ready);
		ready.init();
		assertEquals(originalHash, ready.hashCode());
		if ("storeHash".equals(hashOperation)) {
			valueStore.clearStoredHash(id);
		}
		ExecutorService executor = Executors.newSingleThreadExecutor();
		Future<Integer> hash = null;
		try {
			pauseHash.set(true);
			hash = executor.submit(() -> {
				hashThread.set(Thread.currentThread());
				return ready.hashCode();
			});
			assertTrue("Hash access must capture the current, real dictionary revision before reclamation",
					revisionCaptured.await(5, TimeUnit.SECONDS));
			retireValues(Set.of(id));
			awaitReclamationEligibility(collected);
			evictRetiredValues();
			assertEquals("The replacement must physically reuse the original compound ID", id,
					storeBNodes("hash-association-replacement")[0]);
			releaseHashAccess.countDown();
			assertEquals("An old ready value must retain its own hash across native ID reassignment", originalHash,
					(int) hash.get(5, TimeUnit.SECONDS));
			assertEquals("A late old hash update must not corrupt the replacement's hash", replacementHash,
					valueStore.getLazyValue(id).hashCode());
			assertEquals("hash-association-original", ready.stringValue());
			assertEquals("hash-association-replacement", valueStore.getValue(id).stringValue());
			Reference.reachabilityFence(ready);
		} finally {
			releaseHashAccess.countDown();
			try {
				if (hash != null) {
					hash.get(5, TimeUnit.SECONDS);
				}
			} finally {
				executor.shutdownNow();
				assertTrue("The old hash worker must drain", executor.awaitTermination(5, TimeUnit.SECONDS));
			}
		}
	}

	@ParameterizedTest
	@CsvSource({ "false,false", "false,true", "true,false", "true,true" })
	public void testPendingTripleChildrenRetainTheirOwnNativeCapabilitiesOnAbort(boolean nested, boolean eagerParent)
			throws Exception {
		valueStore.close();
		Set<Long> resolvedIds = ConcurrentHashMap.newKeySet();
		valueStore = new ValueStore(new File(dataDir, "values"), new LmdbStoreConfig()) {

			@Override
			boolean resolveValue(long id, LmdbValue value, ValueStoreRevision revision) {
				resolvedIds.add(id);
				return super.resolveValue(id, value, revision);
			}
		};
		long committedId = storeBNodes("capability-committed-child")[0];
		valueStore.startTransaction(true);
		try {
			Resource committedChild = Values.bnode("capability-committed-child");
			IRI newPredicate = Values.iri("urn:capability:new-predicate");
			Resource newChild = Values.bnode("capability-new-child");
			long predicateId = valueStore.storeValue(newPredicate);
			long newChildId = valueStore.storeValue(newChild);
			TripleTerm inner = Values.tripleTerm(committedChild, newPredicate, newChild);
			long innerId = nested ? valueStore.storeValue(inner) : LmdbValue.UNKNOWN_ID;
			TripleTerm outer = Values.tripleTerm(committedChild, newPredicate, nested ? inner : newChild);
			long parentId = valueStore.storeValue(outer);
			LmdbTripleTerm parent = (LmdbTripleTerm) (eagerParent ? valueStore.getValue(parentId)
					: valueStore.getLazyValue(parentId));
			LmdbValue retainedChild = (LmdbValue) parent.getSubject();
			LmdbValue appendedPredicate = (LmdbValue) parent.getPredicate();
			LmdbValue appendedChild;
			LmdbValue nestedRetainedChild = retainedChild;
			if (nested) {
				LmdbTripleTerm childTerm = (LmdbTripleTerm) parent.getObject();
				nestedRetainedChild = (LmdbValue) childTerm.getSubject();
				appendedChild = (LmdbValue) childTerm.getObject();
				assertEquals("Only the parent and nested term containers may decode before abort",
						eagerParent ? Set.of(innerId) : Set.of(parentId, innerId), resolvedIds);
			} else {
				appendedChild = (LmdbValue) parent.getObject();
				assertEquals("Only the parent term container may decode before abort",
						eagerParent ? Set.of() : Set.of(parentId), resolvedIds);
			}
			assertEquals(committedId, retainedChild.getInternalID());
			assertEquals(predicateId, appendedPredicate.getInternalID());
			assertEquals(newChildId, appendedChild.getInternalID());
			valueStore.rollback();
			assertEquals("An existing unresolved child must retain its committed predecessor capability",
					"capability-committed-child", retainedChild.stringValue());
			assertEquals("Nested existing children must retain the same committed predecessor capability",
					"capability-committed-child", nestedRetainedChild.stringValue());
			assertThrows(SailException.class, appendedPredicate::init,
					"A genuinely appended IRI must retain its aborted writer capability");
			assertThrows(SailException.class, appendedChild::init,
					"A genuinely appended scalar must retain its aborted writer capability");
			valueStore.close();
		} finally {
			valueStore.rollback();
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	public void testEscapedValuesResolveWithOnlyOlderPairedReadersAtCapacity(boolean nested) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig();
		List<ValueStore.ReadSnapshot> snapshots = new ArrayList<>();
		ExecutorService executor = Executors.newSingleThreadExecutor();
		try (TripleStore triples = new TripleStore(new File(dataDir, "borrow-capacity-triples"), config, valueStore);
				TxnManager.ReaderReservation tripleReservation = triples.getTxnManager().reserveReadTxn(false);
				Txn tripleTxn = tripleReservation.startPinned(triples::getDataRevision)) {
			try {
				long id = storeBNodes("borrow-capacity-retired")[0];
				RevisionCollection collected = trackRevisionCollection(valueStore.getLazyValue(id));
				retireValues(Set.of(id));
				for (int i = 0; i < TxnManager.POOL_SIZE - 1; i++) {
					try (ValueStore.ReadSnapshotReservation reservation = valueStore.reserveReadSnapshot()) {
						ValueStore.ReadSnapshot snapshot = reservation.start(tripleTxn);
						snapshot.retainStableIds(tripleTxn);
						snapshots.add(snapshot);
					}
				}
				awaitReclamationEligibility(collected);
				evictRetiredValues();
				assertEquals(id, storeBNodes("borrow-capacity-replacement")[0]);
				Value expected = Values.bnode("borrow-capacity-replacement");
				long escapedId = id;
				if (nested) {
					expected = Values.tripleTerm(Values.iri("urn:borrow-capacity:subject"),
							Values.iri("urn:borrow-capacity:predicate"),
							Values.tripleTerm(Values.bnode("borrow-capacity-replacement"),
									Values.iri("urn:borrow-capacity:predicate"), Values.literal("nested capacity")));
					valueStore.startTransaction(true);
					escapedId = valueStore.storeValue(expected);
					valueStore.commit();
				}
				LmdbValue escaped = valueStore.getLazyValue(escapedId);
				Value expectedValue = expected;
				assertEquals(
						"All ordinary paired handles predate replacement; naked nested resolution must use the "
								+ "reserved short-reader capacity without advancing those snapshots",
						expectedValue, executor.submit(() -> {
							escaped.toString();
							return escaped;
						}).get(5, TimeUnit.SECONDS));
			} finally {
				executor.shutdownNow();
				try {
					assertTrue(executor.awaitTermination(5, TimeUnit.SECONDS));
				} finally {
					for (ValueStore.ReadSnapshot snapshot : snapshots) {
						snapshot.close();
					}
				}
			}
		} finally {
			executor.shutdownNow();
		}
	}

	@ParameterizedTest
	@CsvSource({ "false,false,commit", "false,true,commit", "true,false,commit", "true,true,commit",
			"false,false,rollback", "false,true,rollback", "true,false,rollback", "true,true,rollback",
			"false,false,failed", "false,true,failed", "true,false,failed", "true,true,failed",
			"false,false,checkpoint", "false,true,checkpoint", "true,false,checkpoint", "true,true,checkpoint" })
	public void testWriterLazyAssociationSettlesWithItsNativeTransaction(boolean reclaim, boolean nested,
			String settlement) throws Exception {
		valueStore.close();
		AtomicBoolean failCommit = new AtomicBoolean();
		valueStore = new ValueStore(new File(dataDir, "values"), new LmdbStoreConfig()) {

			@Override
			int commitWriteTransaction(long transaction) {
				if (failCommit.compareAndSet(true, false)) {
					mdb_txn_abort(transaction);
					return MDB_BAD_TXN;
				}
				return super.commitWriteTransaction(transaction);
			}
		};
		long[] originalIds = storeBNodes("pending-retired", "pending-committed");
		LmdbValue oldReady = valueStore.getLazyValue(originalIds[0]);
		RevisionCollection collected = trackRevisionCollection(oldReady);
		oldReady.init();
		if (reclaim) {
			retireValues(Set.of(originalIds[0]));
			awaitReclamationEligibility(collected);
			valueStore.forceEvictionOfValues();
		}
		valueStore.startTransaction(true);
		long newId = valueStore.storeValue(Values.bnode("pending-new"));
		if (reclaim) {
			assertEquals("The writer must really reuse the retired compound ID", originalIds[0], newId);
		}
		Value expected = Values.bnode("pending-new");
		if (nested) {
			expected = Values.tripleTerm(Values.iri("urn:pending:subject"), Values.iri("urn:pending:predicate"),
					Values.tripleTerm((Resource) expected, Values.iri("urn:pending:predicate"),
							Values.literal("pending child")));
			newId = valueStore.storeValue(expected);
		}
		LmdbValue writerShell = valueStore.getLazyValue(newId);
		LmdbValue committedWriterShell = valueStore.getLazyValue(originalIds[1]);
		assertFalse("The new writer shell must remain unresolved through settlement", isInitialized(writerShell));
		ExecutorService executor = Executors.newSingleThreadExecutor();
		try {
			assertEquals("A non-writer reader during the pending transition must use committed identity",
					"pending-committed", executor.submit(() -> valueStore.getLazyValue(originalIds[1]).stringValue())
							.get(5, TimeUnit.SECONDS));
		} finally {
			executor.shutdownNow();
			assertTrue(executor.awaitTermination(5, TimeUnit.SECONDS));
		}
		boolean committed = "commit".equals(settlement) || "checkpoint".equals(settlement);
		if ("failed".equals(settlement)) {
			failCommit.set(true);
			assertThrows(IOException.class, valueStore::commit);
		} else if ("rollback".equals(settlement)) {
			valueStore.rollback();
		} else if ("checkpoint".equals(settlement)) {
			valueStore.endTransaction(true, true);
			valueStore.startTransaction(false);
			valueStore.rollback();
		} else {
			valueStore.commit();
		}
		assertEquals("Already-committed writer reads keep their predecessor capability across settlement",
				"pending-committed", committedWriterShell.stringValue());
		assertEquals("Completed lexical values survive native identity transitions", "pending-retired",
				oldReady.stringValue());
		if (committed) {
			writerShell.toString();
			assertEquals(expected, writerShell);
		} else {
			assertThrows(SailException.class, writerShell::init,
					"A shell whose association was aborted must report invalid identity explicitly");
			if (reclaim) {
				evictRetiredValues();
				assertEquals("The rolled-back reclaimed ID must really be reassigned in the same store", originalIds[0],
						storeBNodes("pending-later-replacement")[0]);
				assertThrows(SailException.class, writerShell::init);
			}
			valueStore.close();
			valueStore = createValueStore();
			valueStore.startTransaction(true);
			valueStore.storeValue(expected);
			valueStore.commit();
			assertThrows(SailException.class, writerShell::init);
		}
	}

	@ParameterizedTest
	@CsvSource({ "false,false", "true,false", "false,true", "true,true" })
	public void testAbortedAppendLazyRejectsSameIdAfterReopen(boolean nested, boolean legacyFormat) throws Exception {
		File directory = new File(dataDir, "aborted-append-" + (legacyFormat ? "format2-" : "format6-")
				+ (nested ? "nested" : "simple"));
		valueStore.close();
		valueStore = legacyFormat ? createLegacyFormat2ValueStore(directory)
				: createValueStore(directory, new LmdbStoreConfig());
		assertFormatProfile(legacyFormat);

		Value original = nested ? Values.tripleTerm(Values.bnode("append-original"), Values.iri("urn:append:predicate"),
				Values.literal("append original")) : Values.bnode("append-original");
		Value replacement = nested ? Values.tripleTerm(Values.bnode("append-replacement"),
				Values.iri("urn:append:predicate"), Values.literal("append replacement"))
				: Values.bnode("append-replacement");
		valueStore.startTransaction(true);
		long id = valueStore.storeValue(original);
		LmdbValue escaped = valueStore.getLazyValue(id);
		assertFalse(isInitialized(escaped));
		valueStore.rollback();
		assertThrows(SailException.class, escaped::init,
				"An unresolved shell cannot retain a native association that its writer aborted");
		valueStore.close();
		valueStore = legacyFormat ? createLegacyFormat2ValueStore(directory)
				: createValueStore(directory, new LmdbStoreConfig());
		assertFormatProfile(legacyFormat);
		valueStore.startTransaction(true);
		long replacementId = valueStore.storeValue(replacement);
		if (legacyFormat) {
			assertEquals("The format-2 writer reuses the appended compound ID after rollback", id, replacementId);
		} else {
			assertTrue("format 6 must reserve the aborted reference ordinal across reopen",
					ValueIds.referenceOrdinal(replacementId) > ValueIds.referenceOrdinal(id));
		}
		valueStore.commit();
		assertThrows(SailException.class, escaped::init,
				"An aborted append capability cannot decode a later environment's association");
		valueStore.close();
	}

	private void assertFormatProfile(boolean legacyFormat) {
		LmdbStoreFormat format = valueStore.getFormat();
		assertEquals(legacyFormat ? LmdbStoreFormat.LEGACY_VERSION : LmdbStoreFormat.CURRENT_VERSION,
				format.getVersion());
		assertEquals(!legacyFormat, format.inlinesLiterals());
		assertEquals(!legacyFormat, format.usesOrderedNumericIds());
		assertEquals(!legacyFormat, format.usesCoreDatatypeLiteralReferences());
		assertEquals(!legacyFormat, format.usesCanonicalLanguageTags());
		assertEquals(!legacyFormat, format.usesZeroFractionDateTimeIds());
	}

