	@Test
	public void testDatatypeCacheKeepsOldAndFreshMeaningsOfAReusedIdSeparate() throws Exception {
		valueStore.close();
		LmdbStoreConfig config = new LmdbStoreConfig().setValueCacheSize(1).setInlineLiterals(false);
		valueStore = createValueStore(new File(dataDir, "datatype-cache-values"), config);
		assertFalse("the opened value format must honor inlineLiterals=false",
				valueStore.getFormat().inlinesLiterals());
		IRI oldDatatype = Values.iri("urn:datatype-cache:old");
		IRI newDatatype = Values.iri("urn:datatype-cache:new");
		valueStore.startTransaction(true);
		long oldLiteralId = valueStore.storeValue(Values.literal("old literal", oldDatatype));
		long oldDatatypeId = valueStore.getId(oldDatatype);
		valueStore.commit();
		RevisionCollection collected = trackRevisionCollection(valueStore.getLazyValue(oldDatatypeId));
		retireValues(Set.of(oldLiteralId));
		try (TripleStore triples = new TripleStore(new File(dataDir, "datatype-cache-reuse-triples"), config,
				valueStore);
				TxnManager.ReaderReservation tripleReservation = triples.getTxnManager().reserveReadTxn(false);
				Txn oldTripleTxn = tripleReservation.startPinned(triples::getDataRevision);
				ValueStore.ReadSnapshotReservation reservation = valueStore.reserveReadSnapshot();
				ValueStore.ReadSnapshot oldSnapshot = reservation.start(oldTripleTxn)) {
			oldSnapshot.retainStableIds(oldTripleTxn);
			awaitRevisionCollection(collected);
			evictRetiredValues();
			valueStore.startTransaction(true);
			long newLiteralId = valueStore.storeValue(Values.literal("new literal", newDatatype));
			long newDatatypeId = valueStore.getId(newDatatype);
			valueStore.commit();
			assertEquals("the real native dictionary must reuse the retired datatype ID", oldDatatypeId, newDatatypeId);
			Literal fresh = (Literal) valueStore.getValue(newLiteralId);
			assertEquals(newDatatype, fresh.getDatatype());
			assertSame("fresh decoding must populate the current datatype cache", fresh.getDatatype(),
					valueStore.cachedDatatype(newDatatypeId));
			Literal old = (Literal) valueStore.getValue(oldSnapshot, oldLiteralId);
			assertEquals("an old native view cannot borrow a fresh ID's datatype meaning", oldDatatype,
					old.getDatatype());
			assertEquals(oldSnapshot.completedRevision(), ((LmdbValue) old.getDatatype()).getValueStoreRevision());
			assertNotEquals(((LmdbValue) fresh.getDatatype()).getValueStoreRevision(),
					((LmdbValue) old.getDatatype()).getValueStoreRevision());
			assertNull("a late old-view cache entry cannot serve the current dictionary",
					valueStore.cachedDatatype(newDatatypeId));
			valueStore.getValue(newDatatypeId);
			Literal freshAgain = (Literal) valueStore.getValue(newLiteralId);
			assertEquals(newDatatype, freshAgain.getDatatype());
			assertSame(freshAgain.getDatatype(), valueStore.cachedDatatype(newDatatypeId));
		}
	}

	private void retireValues(Set<Long> ids) throws IOException {
		valueStore.startTransaction(true);
		Set<Long> pending = ids;
		while (!pending.isEmpty()) {
			Set<Long> next = new HashSet<>();
			valueStore.gcIds(pending, next);
			pending = next;
		}
		valueStore.commit();
	}

	private void evictRetiredValues() throws IOException {
		valueStore.forceEvictionOfValues();
		valueStore.startTransaction(true);
		valueStore.commit();
	}

	private record RevisionCollection(long revisionId, CountDownLatch collected) {
	}

	private RevisionCollection trackRevisionCollection(LmdbValue value) {
		ValueStoreRevision.Lazy revision = ((ValueStoreRevision.Lazy) value.getValueStoreRevision()).epoch();
		CountDownLatch collected = new CountDownLatch(1);
		revisionCleaner.register(revision, collected::countDown);
		return new RevisionCollection(revision.getRevisionId(), collected);
	}

	private void awaitRevisionCollection(RevisionCollection revision) throws InterruptedException {
		awaitCollection(revision.collected());
	}

	private void awaitReclamationEligibility(RevisionCollection revision) throws InterruptedException {
		awaitRevisionCollection(revision);
		// Cleaner callbacks for the same referent have no ordering guarantee. Observe the store's real
		// eligibility publication before asking a writer to reclaim its retired dictionary records.
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
		while (!isReclamationEligible(revision.revisionId()) && System.nanoTime() < deadline) {
			System.gc();
			Thread.yield();
		}
		assertTrue("The collected revision must be eligible before checking reclamation",
				isReclamationEligible(revision.revisionId()));
	}

	private boolean isReclamationEligible(long revisionId) {
		synchronized (valueStore.unusedRevisionIds) {
			return valueStore.unusedRevisionIds.contains(revisionId);
		}
	}

	private void awaitCollection(CountDownLatch collected) throws InterruptedException {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
		while (collected.getCount() != 0 && System.nanoTime() < deadline) {
			System.gc();
			collected.await(100, TimeUnit.MILLISECONDS);
		}
		assertEquals("The unreachable revision must be collected before checking reclamation", 0, collected.getCount());
	}

	@Test
	public void testDatatypeReferencesSurviveTransactionBoundaries() throws Exception {
		IRI datatype = Values.iri("urn:refcount:datatype");
		long[] literalIds = new long[4];
		valueStore.startTransaction(true);
		for (int i = 0; i < 3; i++) {
			literalIds[i] = valueStore.storeValue(Values.literal("literal " + i, datatype));
		}
		valueStore.commit();
		valueStore.startTransaction(true);
		literalIds[3] = valueStore.storeValue(Values.literal("literal 3", datatype));
		valueStore.commit();
		Set<Long> nextIds = new HashSet<>();
		valueStore.startTransaction(true);
		valueStore.gcIds(Collections.singleton(literalIds[3]), nextIds);
		assertTrue("The datatype is still referenced by three surviving literals", nextIds.isEmpty());
		valueStore.commit();
		assertNotEquals(LmdbValue.UNKNOWN_ID, valueStore.getId(datatype));
	}

	@ParameterizedTest
	@ValueSource(strings = { "namespace", "datatype", "triple-component" })
	public void testCheckpointRollbackDoesNotLoseSharedComponentReferences(String componentKind) throws Exception {
		valueStore.close();
		valueStore = new ValueStore(new File(dataDir, "checkpoint-" + componentKind), new LmdbStoreConfig());
		Value sharedComponent;
		Value firstDependent;
		Value checkpointDependent;
		switch (componentKind) {
		case "namespace" -> {
			sharedComponent = Values.iri("urn:refcount:checkpoint:namespace:");
			firstDependent = Values.iri("urn:refcount:checkpoint:namespace:", "first");
			checkpointDependent = Values.iri("urn:refcount:checkpoint:namespace:", "checkpoint");
		}
		case "datatype" -> {
			sharedComponent = Values.iri("urn:refcount:checkpoint:datatype");
			firstDependent = Values.literal("first", (IRI) sharedComponent);
			checkpointDependent = Values.literal("checkpoint", (IRI) sharedComponent);
		}
		case "triple-component" -> {
			sharedComponent = Values.iri("urn:refcount:checkpoint:predicate");
			firstDependent = Values.tripleTerm(Values.bnode("first"), (IRI) sharedComponent,
					Values.literal("first object"));
			checkpointDependent = Values.tripleTerm(Values.bnode("checkpoint"), (IRI) sharedComponent,
					Values.literal("checkpoint object"));
		}
		default -> throw new IllegalArgumentException("Unsupported shared component kind: " + componentKind);
		}
		valueStore.startTransaction(true);
		long firstId = valueStore.storeValue(firstDependent);
		valueStore.commit();
		long sharedComponentId = componentKind.equals("namespace")
				? namespaceIdFromEncodedIri(firstId, (IRI) firstDependent)
				: valueStore.getId(sharedComponent);
		assertEquals("The initial committed dependency establishes one reference", 1L,
				persistedRefCount(sharedComponentId));
		long nativeGenerationBeforeCheckpoint = valueStore.nativeCommitGeneration();
		valueStore.startTransaction(true);
		long checkpointDependentId = valueStore.storeValue(checkpointDependent);
		valueStore.endTransaction(true, true);
		assertEquals("the checkpoint must persist the second dependent mapping", checkpointDependent,
				valueStore.getValue(checkpointDependentId));
		assertTrue("the checkpoint must complete a real native ValueStore commit",
				valueStore.nativeCommitGeneration() > nativeGenerationBeforeCheckpoint);
		valueStore.startTransaction(false);
		valueStore.rollback();
		Set<Long> nextIds = new HashSet<>();
		valueStore.startTransaction(true);
		valueStore.gcIds(Set.of(checkpointDependentId), nextIds);
		valueStore.commit();
		boolean sharedComponentWasQueued = nextIds.contains(sharedComponentId);
		long referenceCountAfterRemoval = persistedRefCount(sharedComponentId);
		valueStore.close();
		valueStore = new ValueStore(new File(dataDir, "checkpoint-" + componentKind), new LmdbStoreConfig());
		long reopenedFirstId = valueStore.getId(firstDependent);
		long reopenedSharedComponentId = componentKind.equals("namespace")
				? namespaceIdFromEncodedIri(reopenedFirstId, (IRI) firstDependent)
				: valueStore.getId(sharedComponent);
		long reopenedReferenceCount = persistedRefCount(reopenedSharedComponentId);
		assertAll("checkpoint commit followed by rollback preserves live shared component references",
				() -> assertFalse("removing the checkpointed dependent must not queue a still-referenced component",
						sharedComponentWasQueued),
				() -> assertEquals("the remaining dependent must retain one persisted reference", 1L,
						referenceCountAfterRemoval),
				() -> assertEquals("the original dependent mapping must survive the checkpoint and removal", firstId,
						reopenedFirstId),
				() -> assertEquals("the shared component mapping must survive reopening", sharedComponentId,
						reopenedSharedComponentId),
				() -> assertEquals("the reopened component count must match its remaining dependent", 1L,
						reopenedReferenceCount));
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	public void testRetiredIdsRemainReclaimableWhenGrowthCheckpointsBeforeFreeingThem(
			boolean rollbackReclamationBeforeRetry) throws Exception {
		valueStore.close();
		LmdbStoreConfig config = new LmdbStoreConfig().setValueDBSize(8L * 1024 * 1024)
				.setAutoGrow(true)
				.setInlineLiterals(false);
		File valuesDirectory = new File(dataDir,
				"retired-ids-before-checkpoint-values-" + rollbackReclamationBeforeRetry);
		valueStore = createValueStore(valuesDirectory, config);
		assertFalse("the initial opened value format must honor inlineLiterals=false",
				valueStore.getFormat().inlinesLiterals());
		int cohortSize = 4_096;
		String[] labels = new String[cohortSize];
		for (int i = 0; i < labels.length; i++) {
			labels[i] = "pre-free-checkpoint-" + i;
		}
		long[] retiredIds = storeBNodes(labels);
		Set<Long> retiredIdSet = Arrays.stream(retiredIds).boxed().collect(Collectors.toSet());
		long retainedId = retiredIds[0];
		LmdbValue retainedValue = valueStore.getLazyValue(retainedId);
		long retainedRevisionId = retainedValue.getValueStoreRevision().getRevisionId();
		RevisionCollection retainedRevisionCollected = trackRevisionCollection(retainedValue);
		retireValues(retiredIdSet);
		assertEquals("the retirement transaction must remove the old dictionary mappings", LmdbValue.UNKNOWN_ID,
				valueStore.getId(Values.bnode(labels[0])));
		assertEquals("the full retired cohort must remain in the native unused-ID index until reclaimed", cohortSize,
				countValueDatabaseEntries("unused_ids"));
		long candidateGrowthBytes = countValueDatabaseEntries("unused_ids") * (2L + Long.BYTES);
		int fillerValuesPerBatch = 4;
		int fillerValueLength = Math.toIntExact(candidateGrowthBytes / (2L * fillerValuesPerBatch)) - 64;
		assertTrue("the cohort must provide a bounded, nonempty native reclamation estimate",
				candidateGrowthBytes > 0 && fillerValueLength > 0);
		long fillerPayloadBytes = (long) fillerValuesPerBatch * fillerValueLength;
		assertTrue("one committed filler batch must be smaller than the measured cohort reclamation estimate",
				fillerPayloadBytes < candidateGrowthBytes);

		long initialMapSize = valueStore.mapSizeBytes();
		long initialMapGeneration = valueStore.nativeMapGeneration();
		List<Value> committedFillers = new ArrayList<>();
		valueStore.startTransaction(true);
		for (int index = 0; index < fillerValuesPerBatch; index++) {
			Value filler = Values.literal("committed-pressure-" + index + ":" + "x".repeat(fillerValueLength));
			valueStore.storeValue(filler);
			committedFillers.add(filler);
		}
		valueStore.commit();
		int committedBatches = 1;
		// Native prepared-value reservations include page bookkeeping. Fill an independent native database to
		// the measured policy watermark instead of mistaking a larger reservation for this cohort's demand.
		int capacityDbi = valueStore.writeTransaction(
				(stack, txn) -> openDatabaseWithTxn(txn, "reclamation_capacity", MDB_CREATE));
		long watermark = initialMapSize - LmdbUtil.MIN_FREE_SPACE;
		MapGrowthPolicy pressurePolicy = new MapGrowthPolicy(config.getMapGrowthThreshold());
		long maximumEntries = initialMapSize / candidateGrowthBytes + 2L;
		for (int entry = 0; !pressurePolicy.hardCapacityRequired(initialMapSize, valueStore.occupiedBytes(),
				candidateGrowthBytes); entry++) {
			assertTrue("native pressure must reach the exact cohort watermark within bounded capacity",
					entry < maximumEntries);
			int payload = Math.toIntExact(Math.min(1024 * 1024L,
					Math.max(1L, watermark - valueStore.occupiedBytes() - candidateGrowthBytes)));
			int keyId = entry;
			valueStore.writeTransaction((stack, txn) -> {
				MDBVal key = MDBVal.calloc(stack);
				key.mv_data(stack.malloc(Integer.BYTES).putInt(keyId).flip());
				MDBVal data = MDBVal.calloc(stack);
				data.mv_data(ByteBuffer.allocateDirect(payload));
				E(mdb_put(txn, capacityDbi, key, data, 0));
				return null;
			});
		}
		AtomicInteger preResizeCallbacks = new AtomicInteger();
		IllegalStateException stopBeforeResize = new IllegalStateException("stop before native map resize");
		valueStore.setResizeCheckpointListener(() -> {
			preResizeCallbacks.incrementAndGet();
			throw stopBeforeResize;
		});
		long nativeGenerationBeforeFailedBatch = valueStore.nativeCommitGeneration();
		valueStore.startTransaction(true);
		try {
			assertSame(stopBeforeResize, assertThrows(IllegalStateException.class,
					() -> valueStore.storeValue(Values.literal("marked-pressure:" + "x".repeat(fillerValueLength)))));
		} finally {
			valueStore.rollback();
		}
		boolean stoppedBeforeResize = preResizeCallbacks.get() == 1;

		long mapSizeAfterMarker = valueStore.mapSizeBytes();
		long mapGenerationAfterMarker = valueStore.nativeMapGeneration();
		long nativeGenerationAfterMarker = valueStore.nativeCommitGeneration();
		long occupiedAfterMarker = valueStore.occupiedBytes();
		boolean cohortDemandWouldResize = valueStore.requiresResizeForEstimatedWrite(candidateGrowthBytes);
		String pressureDiagnostic = "map=" + initialMapSize + "->" + mapSizeAfterMarker + ", mapGeneration="
				+ initialMapGeneration + "->" + mapGenerationAfterMarker + ", nativeGeneration="
				+ nativeGenerationBeforeFailedBatch + "->" + nativeGenerationAfterMarker + ", occupied="
				+ occupiedAfterMarker + ", candidateBytes=" + candidateGrowthBytes + ", fillerPayloadBytes="
				+ fillerPayloadBytes + ", committedBatches=" + committedBatches + ", callbackCount="
				+ preResizeCallbacks.get();
		assertTrue(
				"bounded committed values must reach a real growth checkpoint before map mutation: "
						+ pressureDiagnostic,
				stoppedBeforeResize && committedBatches > 0 && preResizeCallbacks.get() == 1);
		assertEquals("the marker must stop resize before changing native map capacity", initialMapSize,
				mapSizeAfterMarker);
		assertEquals("the marker must stop resize before advancing map generation", initialMapGeneration,
				mapGenerationAfterMarker);
		assertEquals("rolling back the marked filler batch must not commit native data",
				nativeGenerationBeforeFailedBatch, nativeGenerationAfterMarker);
		assertTrue("the real cohort estimate must still request growth after the failed small batch: "
				+ pressureDiagnostic, cohortDemandWouldResize);
		Reference.reachabilityFence(retainedValue);
		retainedValue = null;
		awaitReclamationEligibility(retainedRevisionCollected);
		assertTrue("the collected lazy epoch must produce a real reclamation candidate",
				valueStore.unusedRevisionIds.contains(retainedRevisionId));
		valueStore.forceEvictionOfValues();
		AtomicInteger growthCheckpoints = new AtomicInteger();
		valueStore.setResizeCheckpointListener(growthCheckpoints::incrementAndGet);
		long mapSizeBeforeReclamation = valueStore.mapSizeBytes();
		long mapGenerationBeforeReclamation = valueStore.nativeMapGeneration();
		long nativeGenerationBeforeReclamation = valueStore.nativeCommitGeneration();
		assertTrue("the actual unused-ID cohort must require a resize before reclamation",
				valueStore.requiresResizeForEstimatedWrite(candidateGrowthBytes));
		valueStore.startTransaction(true);
		long mapSizeAfterReclamation = valueStore.mapSizeBytes();
		long mapGenerationAfterReclamation = valueStore.nativeMapGeneration();
		long nativeGenerationAfterReclamation = valueStore.nativeCommitGeneration();
		String checkpointDiagnostic = "map=" + mapSizeBeforeReclamation + "->" + mapSizeAfterReclamation
				+ ", mapGeneration=" + mapGenerationBeforeReclamation + "->" + mapGenerationAfterReclamation
				+ ", nativeGeneration=" + nativeGenerationBeforeReclamation + "->" + nativeGenerationAfterReclamation
				+ ", checkpointCallbacks=" + growthCheckpoints.get() + ", cohortDemandBytes=" + candidateGrowthBytes;
		assertTrue("the test must cross the real ValueStore checkpoint before reclamation: " + checkpointDiagnostic,
				growthCheckpoints.get() > 0 && mapSizeAfterReclamation > mapSizeBeforeReclamation
						&& mapGenerationAfterReclamation > mapGenerationBeforeReclamation
						&& nativeGenerationAfterReclamation > nativeGenerationBeforeReclamation);
		if (rollbackReclamationBeforeRetry) {
			valueStore.rollback();
			long unusedIdsAfterRollback = countValueDatabaseEntries("unused_ids");
			boolean retainedCandidateAfterRollback = valueStore.unusedRevisionIds.contains(retainedRevisionId);
			assertAll("rollback must keep the physically uncommitted reclamation cohort eligible",
					() -> assertEquals(cohortSize, unusedIdsAfterRollback),
					() -> assertTrue(retainedCandidateAfterRollback));
			valueStore.forceEvictionOfValues();
			valueStore.startTransaction(true);
		}
		Value replacement = Values.bnode("after-pre-free-checkpoint-replacement");
		try {
			long replacementId = valueStore.storeValue(replacement);
			assertTrue("the committed retirement cohort must be reused after checkpoint growth; " + checkpointDiagnostic
					+ ", rollbackRetry=" + rollbackReclamationBeforeRetry + ", replacementId=" + replacementId
					+ ", retiredIdCount=" + retiredIdSet.size(), retiredIdSet.contains(replacementId));
			valueStore.commit();
			assertEquals("the resize checkpoint must finish freeing the retired cohort", 0L,
					countValueDatabaseEntries("unused_ids"));
		} finally {
			valueStore.rollback();
		}
		valueStore.close();
		valueStore = createValueStore(valuesDirectory, config);
		assertFalse("the reopened value format must honor inlineLiterals=false",
				valueStore.getFormat().inlinesLiterals());
		long reopenedReplacementId = valueStore.getId(replacement);
		assertTrue("the exact reused ID must survive closing and reopening",
				retiredIdSet.contains(reopenedReplacementId));
		assertEquals(replacement, valueStore.getValue(reopenedReplacementId));
		for (int i = 0; i < labels.length; i++) {
			assertEquals("every retired original mapping must remain absent after its ID was reused",
					LmdbValue.UNKNOWN_ID, valueStore.getId(Values.bnode(labels[i])));
		}
		for (Value filler : committedFillers) {
			long fillerId = valueStore.getId(filler);
			assertNotEquals("every previously committed pressure value must survive growth and reopen",
					LmdbValue.UNKNOWN_ID, fillerId);
			assertEquals("growth and reopen must retain each exact pressure value", filler,
					valueStore.getValue(fillerId));
		}
	}

	@Test
	public void testCheckpointRefCountMapFullRollsBackMappingsAndCounts() throws Exception {
		valueStore.close();
		File constrainedDirectory = new File(dataDir, "checkpoint-refcount-pressure");
		LmdbStoreConfig config = new LmdbStoreConfig().setValueDBSize(1024L * 1024).setAutoGrow(false);
		valueStore = new ValueStore(constrainedDirectory, config);
		IRI datatype = Values.iri("urn:refcount:checkpoint-pressure:datatype");
		Value firstDependent = Values.literal("first dependent " + "f".repeat(256), datatype);
		Value checkpointDependent = Values.literal("checkpoint dependent " + "c".repeat(256), datatype);
		valueStore.startTransaction(true);
		long firstId = valueStore.storeValue(firstDependent);
		valueStore.commit();
		long datatypeId = valueStore.getId(datatype);
		assertEquals("the seed establishes one committed datatype reference", 1L, persistedRefCount(datatypeId));
		long generationBeforeCheckpoint = valueStore.nativeCommitGeneration();
		valueStore.startTransaction(true);
		long checkpointId = valueStore.storeValue(checkpointDependent);
		int capacityDbi = valueStore
				.writeTransaction((stack, txn) -> openDatabaseWithTxn(txn, "checkpoint_refcount_capacity", MDB_CREATE));
		long mapSize = valueStore.mapSizeBytes();
		int pageSize = valueStore.writeTransaction((stack, txn) -> {
			MDBStat stat = MDBStat.calloc(stack);
			E(mdb_stat(txn, capacityDbi, stat));
			return stat.ms_psize();
		});
		boolean fillerStoppedBeforeMapFull = false;
		long remainingPagesBeforeCheckpoint = -1;
		for (int entry = 0; entry < 20_000; entry++) {
			int keyValue = entry;
			long remainingPages = valueStore.writeTransaction((stack, txn) -> {
				long highWater = LmdbUtil.getNewSize(pageSize, txn, 0L);
				long pagesAvailable = Math.max(0L, (mapSize - highWater) / pageSize);
				if (pagesAvailable <= 1L) {
					return -pagesAvailable - 1L;
				}
				MDBVal key = MDBVal.calloc(stack);
				key.mv_data(stack.malloc(Integer.BYTES).putInt(keyValue).flip());
				MDBVal data = MDBVal.calloc(stack);
				data.mv_data(stack.calloc(2_048));
				E(mdb_put(txn, capacityDbi, key, data, 0));
				long updatedHighWater = LmdbUtil.getNewSize(pageSize, txn, 0L);
				return Math.max(0L, (mapSize - updatedHighWater) / pageSize);
			});
			if (remainingPages < 0L) {
				fillerStoppedBeforeMapFull = true;
				remainingPagesBeforeCheckpoint = -remainingPages - 1L;
				break;
			}
		}
		IOException checkpointFailure = null;
		try {
			valueStore.endTransaction(true, true);
		} catch (IOException failure) {
			checkpointFailure = failure;
		}
		String checkpointFailureDetails = checkpointFailure == null ? "<no checkpoint exception>"
				: checkpointFailure.getClass().getName() + ": " + checkpointFailure.getMessage() + "\n"
						+ Arrays.toString(checkpointFailure.getStackTrace());
		String checkpointDiagnostic = "remainingPages=" + remainingPagesBeforeCheckpoint + "; "
				+ checkpointFailureDetails;
		System.out.println("Checkpoint capacity failure diagnostic: " + checkpointDiagnostic);
		boolean countWriteWasTheFailingOperation = checkpointFailure != null
				&& Arrays.stream(checkpointFailure.getStackTrace())
						.anyMatch(frame -> frame.getClassName().equals(ValueStore.class.getName())
								&& frame.getMethodName().equals("updateRefCounts"));
		boolean checkpointWasMapFull = checkpointFailure instanceof LmdbUtil.MapFullException
				&& checkpointFailure.getMessage() != null && checkpointFailure.getMessage().contains("MDB_MAP_FULL");
		long generationAfterFailedCheckpoint = valueStore.nativeCommitGeneration();
		valueStore.rollback();
		valueStore.close();
		valueStore = new ValueStore(constrainedDirectory, config);
		long reopenedFirstId = valueStore.getId(firstDependent);
		long reopenedDatatypeId = valueStore.getId(datatype);
		long reopenedCheckpointId = valueStore.getId(checkpointDependent);
		long reopenedDatatypeCount = persistedRefCount(reopenedDatatypeId);
		boolean observedFillerStoppedBeforeMapFull = fillerStoppedBeforeMapFull;
		long observedRemainingPagesBeforeCheckpoint = remainingPagesBeforeCheckpoint;
		IOException observedCheckpointFailure = checkpointFailure;
		boolean observedCountWriteFailure = countWriteWasTheFailingOperation;
		boolean observedCheckpointWasMapFull = checkpointWasMapFull;
		ValueStore reopenedStore = valueStore;
		assertAll("a count-write capacity failure aborts the entire ValueStore checkpoint", () -> assertTrue(
				"bounded filler writes must stop before native MAP_FULL with at most one measured page remaining: "
						+ observedRemainingPagesBeforeCheckpoint,
				observedFillerStoppedBeforeMapFull && observedRemainingPagesBeforeCheckpoint <= 1L),
				() -> assertNotNull("the checkpoint refcount write must fail when its native pages are exhausted",
						observedCheckpointFailure),
				() -> assertTrue("checkpoint failure must be the actual MDB_MAP_FULL exception from updateRefCounts: "
						+ checkpointDiagnostic, observedCheckpointWasMapFull),
				() -> assertTrue(
						"the captured failure must originate in updateRefCounts rather than dictionary insertion: "
								+ checkpointDiagnostic,
						observedCountWriteFailure),
				() -> assertEquals("the failed checkpoint must not advance ValueStore's native commit generation",
						generationBeforeCheckpoint, generationAfterFailedCheckpoint),
				() -> assertEquals("the prior committed dependent mapping must survive rollback and reopening", firstId,
						reopenedFirstId),
				() -> assertEquals("the shared datatype mapping must remain stable after rollback and reopening",
						datatypeId, reopenedDatatypeId),
				() -> assertEquals("the failed checkpoint's new dependent mapping must remain absent",
						LmdbValue.UNKNOWN_ID, reopenedCheckpointId),
				() -> assertEquals("the prior committed datatype count must remain exact after rollback and reopening",
						1L, reopenedDatatypeCount),
				() -> assertEquals("the original dependent value must decode exactly after reopening", firstDependent,
						reopenedStore.getValue(reopenedFirstId)));
	}

	private long namespaceIdFromEncodedIri(long iriId, IRI expectedIri) throws IOException {
		byte[] iriData = valueStore.getData(iriId);
		assertEquals("an IRI mapping starts with the URI value marker", 0, iriData[0]);
		ByteBuffer namespaceIdBuffer = ByteBuffer.wrap(iriData, 1, iriData.length - 1);
		long namespaceId = Varint.readUnsigned(namespaceIdBuffer);
		byte[] namespaceData = valueStore.getData(namespaceId);
		assertEquals("the referenced component is an encoded namespace", 4, namespaceData[0]);
		assertArrayEquals("the namespace entry retains its exact UTF-8 bytes",
				expectedIri.getNamespace().getBytes(StandardCharsets.UTF_8),
				Arrays.copyOfRange(namespaceData, 1, namespaceData.length));
		assertArrayEquals("the IRI mapping retains its exact local-name bytes",
				expectedIri.getLocalName().getBytes(StandardCharsets.UTF_8),
				Arrays.copyOfRange(iriData, namespaceIdBuffer.position(), iriData.length));
		return namespaceId;
	}

