	@Test
	public void testLegacyCountsRebuiltFromActiveHashedValues() throws Exception {
		IRI datatype = Values.iri("urn:refcount:legacy-datatype");
		valueStore.startTransaction(true);
		// Equal-length CRC32 collisions exercise both HASH and HASHID forward mappings.
		long firstId = valueStore.storeValue(Values.literal("long literal prefix plumless", datatype));
		long secondId = valueStore.storeValue(Values.literal("long literal prefix buckeroo", datatype));
		long retiredId = valueStore.storeValue(Values.literal("retired literal", datatype));
		valueStore.commit();
		valueStore.startTransaction(true);
		valueStore.gcIds(Collections.singleton(retiredId), new HashSet<>());
		valueStore.commit();
		long datatypeId = valueStore.getId(datatype);
		assertEquals(LmdbStoreFormat.CURRENT_VERSION, valueStore.getFormat().getVersion());
		valueStore.close();
		File directory = new File(dataDir, "values");
		long cleanTransaction = assertClosedCleanRefCountMarker(directory);
		List<NativeDictionaryOwner> owners = inspectNativeStore(directory,
				(stack, txn) -> List.of(captureNativeDictionaryOwner(stack, txn, datatypeId),
						captureNativeDictionaryOwner(stack, txn, firstId),
						captureNativeDictionaryOwner(stack, txn, secondId)));
		assertEquals("the first colliding owner uses the native HASH association", ValueStoreRecordCodec.HASH_KEY,
				owners.get(1).forwardKey()[0]);
		assertEquals("the second colliding owner uses the native HASHID association", ValueStoreRecordCodec.HASHID_KEY,
				owners.get(2).forwardKey()[0]);
		assertNotEquals("collision owners have different real forward associations",
				ByteBuffer.wrap(owners.get(1).forwardKey()), ByteBuffer.wrap(owners.get(2).forwardKey()));
		mutateClosedNativeStore(directory, (stack, txn) -> {
			replaceRefCount(stack, txn, datatypeId, 1);
			return null;
		});
		assertClosedExternalRefCountInput(directory, cleanTransaction, datatypeId, 1);
		inspectNativeStore(directory, (stack, txn) -> {
			for (NativeDictionaryOwner owner : owners) {
				assertNativeDictionaryOwner(stack, txn, owner, true);
			}
			return null;
		});
		valueStore = createValueStore();
		assertEquals("Count only surviving literal forward mappings", 2L, persistedRefCount(datatypeId));
		assertNull(valueStore.getValue(retiredId));
		valueStore.close();
		valueStore = createValueStore();
		assertEquals("Completed migration must survive a second reopen", 2L, persistedRefCount(datatypeId));
	}

