	private void assertResolvedCurrentFormatCapabilities(LmdbStoreFormat expected, LmdbStoreFormat actual) {
		assertEquals(LmdbStoreFormat.CURRENT_VERSION, actual.getVersion());
		assertFalse(actual.isLegacy());
		assertEquals("reopen retains actual persisted inline capability", expected.inlinesLiterals(),
				actual.inlinesLiterals());
		assertEquals("reopen retains actual persisted numeric capability", expected.usesOrderedNumericIds(),
				actual.usesOrderedNumericIds());
		assertEquals("reopen retains actual persisted datatype capability",
				expected.usesCoreDatatypeLiteralReferences(),
				actual.usesCoreDatatypeLiteralReferences());
		assertEquals("reopen retains actual persisted language capability", expected.usesCanonicalLanguageTags(),
				actual.usesCanonicalLanguageTags());
		assertEquals("reopen retains actual persisted date capability", expected.usesZeroFractionDateTimeIds(),
				actual.usesZeroFractionDateTimeIds());
	}

	private void assertStructuredRefCountCompletionUntrusted(MemoryStack stack, long txn) throws IOException {
		MDBVal key = MDBVal.calloc(stack).mv_data(stack.bytes((byte) 0));
		MDBVal data = MDBVal.calloc(stack);
		int result = E(mdb_get(txn, openDatabaseWithTxn(txn, "ref_counts", 0), key, data));
		if (result == MDB_NOTFOUND) {
			return;
		}
		assertEquals(MDB_SUCCESS, result);
		byte[] marker = nativeBytes(data);
		assertEquals("failed current-format recovery retains only a structured DIRTY marker or absence", 18,
				marker.length);
		ByteBuffer fields = ByteBuffer.wrap(marker);
		assertEquals("RCFT magic", 0x52434654, fields.getInt());
		assertEquals("RCFT schema", 1, fields.get());
		assertEquals("incomplete recovery cannot author CLEAN", 0, fields.get());
		assertTrue("DIRTY provenance cannot name a future native generation", fields.getLong() <= mdb_txn_id(txn));
		CRC32 checksum = new CRC32();
		checksum.update(marker, 0, 14);
		assertEquals("incomplete marker checksum covers its native provenance", checksum.getValue(),
				Integer.toUnsignedLong(fields.getInt()));
	}

	/** The independent native completion protocol, not the obsolete StoreProperties ref_counts_version. */
	private long assertClosedCleanRefCountMarker(File directory) throws IOException {
		return inspectNativeStore(directory, (stack, txn) -> {
			MDBVal key = MDBVal.calloc(stack).mv_data(stack.bytes((byte) 0));
			MDBVal value = MDBVal.calloc(stack);
			assertEquals(MDB_SUCCESS, mdb_get(txn, openDatabaseWithTxn(txn, "ref_counts", 0), key, value));
			byte[] marker = nativeBytes(value);
			assertEquals("RCFT structured marker has one exact native schema", 18, marker.length);
			ByteBuffer fields = ByteBuffer.wrap(marker);
			assertEquals("RCFT magic", 0x52434654, fields.getInt());
			assertEquals("RCFT schema", 1, fields.get());
			assertEquals("only a clean completion qualifies this generation", 1, fields.get());
			long transaction = fields.getLong();
			assertEquals("completion names this exact native snapshot", mdb_txn_id(txn), transaction);
			CRC32 checksum = new CRC32();
			checksum.update(marker, 0, 14);
			assertEquals("completion checksum covers all preceding fields", checksum.getValue(),
					Integer.toUnsignedLong(fields.getInt()));
			return transaction;
		});
	}

	private void assertClosedExternalRefCountInput(File directory, long cleanTransaction, long id, long count)
			throws IOException {
		inspectNativeStore(directory, (stack, txn) -> {
			assertTrue("independent corruption advances the real native generation",
					mdb_txn_id(txn) > cleanTransaction);
			assertMigrationMarkerAbsent(stack, txn);
			assertEquals("the exact corrupted count is present before opening", count, nativeRefCount(stack, txn, id));
			return null;
		});
	}

	private Map<Long, Long> closedNativeRefCounts(File directory) throws IOException {
		return inspectNativeStore(directory, (stack, txn) -> {
			Map<Long, Long> counts = new HashMap<>();
			PointerBuffer pointer = stack.mallocPointer(1);
			E(mdb_cursor_open(txn, openDatabaseWithTxn(txn, "ref_counts", 0), pointer));
			long cursor = pointer.get(0);
			try {
				MDBVal key = MDBVal.calloc(stack);
				MDBVal data = MDBVal.calloc(stack);
				for (int rc = E(mdb_cursor_get(cursor, key, data, MDB_FIRST)); rc == MDB_SUCCESS; rc = E(
						mdb_cursor_get(cursor, key, data, MDB_NEXT))) {
					ByteBuffer bytes = key.mv_data().duplicate();
					if (bytes.get(bytes.position()) == 0) {
						continue;
					}
					assertEquals(ValueStoreRecordCodec.ID_KEY, bytes.get());
					counts.put(Varint.readUnsigned(bytes), Varint.readUnsigned(data.mv_data().duplicate()));
				}
			} finally {
				mdb_cursor_close(cursor);
			}
			return Map.copyOf(counts);
		});
	}

	private record NativeDictionaryOwner(long id, byte[] reverse, byte[] forwardKey, byte[] forwardValue) {
	}

	private long nativeIdFromAssociation(MDBVal key, MDBVal data) {
		byte[] value = nativeBytes(data);
		if (value.length > 0 && value[0] == ValueStoreRecordCodec.ID_KEY) {
			return valueStore.data2id(ByteBuffer.wrap(value));
		}
		assertEquals("a collision association stores its owner in the HASHID key", 0, value.length);
		ByteBuffer encodedKey = ByteBuffer.wrap(nativeBytes(key));
		assertEquals("a collision association uses the HASHID marker", ValueStoreRecordCodec.HASHID_KEY,
				encodedKey.get());
		Varint.readUnsigned(encodedKey);
		assertEquals("a collision association key embeds an ID record", ValueStoreRecordCodec.ID_KEY,
				encodedKey.get(encodedKey.position()));
		long id = valueStore.data2id(encodedKey);
		assertFalse("an ID record consumes the full HASHID key suffix", encodedKey.hasRemaining());
		return id;
	}

	private NativeDictionaryOwner captureNativeDictionaryOwner(MemoryStack stack, long txn, long id)
			throws IOException {
		int main = openDatabaseWithTxn(txn, null, 0);
		MDBVal key = MDBVal.calloc(stack).mv_data(stack.bytes(ValueStoreRecordCodec.idKey(id)));
		MDBVal data = MDBVal.calloc(stack);
		assertEquals("capture an actual reverse record", MDB_SUCCESS, mdb_get(txn, main, key, data));
		byte[] reverse = nativeBytes(data);
		byte[] forward = reverse.length <= ValueStoreRecordCodec.MAX_INLINE_KEY_BYTES ? reverse
				: ValueStoreRecordCodec.hashKey(ValueStoreRecordCodec.hash(reverse));
		key.mv_data(stack.bytes(forward));
		int result = E(mdb_get(txn, main, key, data));
		if (result != MDB_SUCCESS || nativeIdFromAssociation(key, data) != id) {
			assertTrue("only a real colliding hash owner needs its per-ID association",
					reverse.length > ValueStoreRecordCodec.MAX_INLINE_KEY_BYTES);
			forward = ValueStoreRecordCodec.collisionKey(ValueStoreRecordCodec.hash(reverse), id);
			key.mv_data(stack.bytes(forward));
			result = E(mdb_get(txn, main, key, data));
		}
		assertEquals("capture the actual active forward association", MDB_SUCCESS, result);
		assertEquals(id, nativeIdFromAssociation(key, data));
		return new NativeDictionaryOwner(id, reverse, forward.clone(), nativeBytes(data));
	}

	private void assertNativeDictionaryOwner(MemoryStack stack, long txn, NativeDictionaryOwner owner,
			boolean forwardPresent) throws IOException {
		int main = openDatabaseWithTxn(txn, null, 0);
		MDBVal key = MDBVal.calloc(stack).mv_data(stack.bytes(ValueStoreRecordCodec.idKey(owner.id())));
		MDBVal data = MDBVal.calloc(stack);
		assertEquals(MDB_SUCCESS, mdb_get(txn, main, key, data));
		assertArrayEquals("the captured reverse bytes remain exact", owner.reverse(), nativeBytes(data));
		key.mv_data(stack.bytes(owner.forwardKey()));
		int result = E(mdb_get(txn, main, key, data));
		if (forwardPresent) {
			assertEquals("the exact active forward key remains", MDB_SUCCESS, result);
			assertArrayEquals("the captured forward value remains exact", owner.forwardValue(), nativeBytes(data));
		} else {
			assertEquals("only the real retired owner's forward key was removed", MDB_NOTFOUND, result);
		}
	}

	private static byte[] nativeBytes(MDBVal value) {
		byte[] bytes = new byte[Math.toIntExact(value.mv_size())];
		value.mv_data().duplicate().get(bytes);
		return bytes;
	}

	private void putExternalUnusedHint(MemoryStack stack, long txn, long revision, long id) throws IOException {
		MDBVal key = MDBVal.calloc(stack).mv_data(stack.bytes(externalUnusedKey(revision, id)));
		E(mdb_put(txn, openDatabaseWithTxn(txn, "unused_ids", 0), key, MDBVal.calloc(stack), 0));
	}

	private byte[] externalUnusedKey(long revision, long id) {
		ByteBuffer bytes = ByteBuffer.allocate(32);
		Varint.writeUnsigned(bytes, revision);
		bytes.put(ValueStoreRecordCodec.idKey(id));
		return Arrays.copyOf(bytes.array(), bytes.position());
	}

	private void assertExternalUnusedHint(MemoryStack stack, long txn, long revision, long id) throws IOException {
		MDBVal key = MDBVal.calloc(stack).mv_data(stack.bytes(externalUnusedKey(revision, id)));
		assertEquals(MDB_SUCCESS, mdb_get(txn, openDatabaseWithTxn(txn, "unused_ids", 0), key, MDBVal.calloc(stack)));
		MDBStat stat = MDBStat.calloc(stack);
		E(mdb_stat(txn, openDatabaseWithTxn(txn, "unused_ids", 0), stat));
		assertEquals("the one captured real owner has one pending hint", 1L, stat.ms_entries());
	}

	private void fillClosedNativeMapToCapacity(File directory, long actualMapSize, long corruptedId)
			throws IOException {
		long env;
		try (MemoryStack stack = stackPush()) {
			PointerBuffer pointer = stack.mallocPointer(1);
			E(mdb_env_create(pointer));
			env = pointer.get(0);
		}
		try {
			E(mdb_env_set_maxdbs(env, 18));
			E(mdb_env_set_mapsize(env, actualMapSize));
			E(mdb_env_open(env, directory.getAbsolutePath(), MDB_NOTLS, 0664));
			// Every writer in this fixed-map fixture uses the owner's captured physical map size.
			LmdbUtil.writeTransaction(env,
					(stack, txn) -> {
						replaceRefCount(stack, txn, corruptedId, 17);
						return null;
					});
			int maximumEntries = Math.toIntExact(actualMapSize / 2048L + 1L);
			for (int filler = 0; filler < maximumEntries; filler++) {
				int entry = filler;
				try {
					LmdbUtil.writeTransaction(env, (stack, txn) -> {
						MDBVal key = MDBVal.calloc(stack).mv_data(stack.malloc(Integer.BYTES).putInt(entry).flip());
						MDBVal data = MDBVal.calloc(stack).mv_data(stack.calloc(2048));
						E(mdb_put(txn, openDatabaseWithTxn(txn, "migration_capacity", MDB_CREATE), key, data, 0));
						return null;
					});
				} catch (LmdbUtil.LmdbException full) {
					assertEquals("the bounded raw writer reached actual native capacity", MDB_MAP_FULL, full.errorCode);
					return;
				}
			}
			throw new AssertionError("physical payload bound exhausted without native MDB_MAP_FULL");
		} finally {
			mdb_env_close(env);
		}
	}

	private <T> T inspectNativeStore(File directory, LmdbUtil.Transaction<T> inspection) throws IOException {
		long env;
		try (MemoryStack stack = stackPush()) {
			PointerBuffer pp = stack.mallocPointer(1);
			E(mdb_env_create(pp));
			env = pp.get(0);
		}
		try {
			E(mdb_env_set_maxdbs(env, 18));
			E(mdb_env_open(env, directory.getAbsolutePath(), MDB_NOTLS, 0664));
			return LmdbUtil.readTransaction(env, inspection);
		} finally {
			mdb_env_close(env);
		}
	}

	private void assertNativeRecordExists(MemoryStack stack, long txn, long id) throws IOException {
		MDBVal key = MDBVal.calloc(stack);
		key.mv_data(valueStore.id2data(valueStore.idBuffer(stack), id).flip());
		assertEquals(MDB_SUCCESS, mdb_get(txn, openDatabaseWithTxn(txn, null, 0), key, MDBVal.calloc(stack)));
	}

	private long nativeRefCount(MemoryStack stack, long txn, long id) throws IOException {
		MDBVal key = MDBVal.calloc(stack);
		key.mv_data(valueStore.id2data(valueStore.idBuffer(stack), id).flip());
		MDBVal data = MDBVal.calloc(stack);
		return mdb_get(txn, openDatabaseWithTxn(txn, "ref_counts", 0), key, data) == MDB_SUCCESS
				? Varint.readUnsigned(data.mv_data())
				: 0L;
	}

	private void assertMigrationMarkerAbsent(MemoryStack stack, long txn) throws IOException {
		MDBVal key = MDBVal.calloc(stack);
		key.mv_data(stack.bytes((byte) 0));
		assertNotEquals(MDB_SUCCESS,
				mdb_get(txn, openDatabaseWithTxn(txn, "ref_counts", 0), key, MDBVal.calloc(stack)));
	}

	private void replaceLegacyRefCount(long id, long count) throws IOException {
		valueStore.writeTransaction((stack, txn) -> {
			int countsDbi = openDatabaseWithTxn(txn, "ref_counts", 0);
			// Legacy stores have counts but no migration marker.
			E(mdb_drop(txn, countsDbi, false));
			if (count == 0) {
				return null;
			}
			MDBVal key = MDBVal.calloc(stack);
			key.mv_data(valueStore.id2data(valueStore.idBuffer(stack), id).flip());
			MDBVal data = MDBVal.calloc(stack);
			ByteBuffer countBuffer = stack.malloc(Long.BYTES + 1);
			Varint.writeUnsigned(countBuffer, count);
			data.mv_data(countBuffer.flip());
			E(mdb_put(txn, countsDbi, key, data, 0));
			return null;
		});
	}

	private static final int LONG_LIVED_READER_BATCHES = 600;

	@Test
	public void reopenRecoversCompactNextIdCounter() throws Exception {
		valueStore.startTransaction(true);
		long firstId = valueStore.storeValue(valueStore.createIRI("urn:test:recover:first"));
		valueStore.commit();
		long firstValue = ValueIds.getValue(firstId);
		valueStore.close();
		valueStore = createValueStore();
		valueStore.startTransaction(true);
		long secondId = valueStore.storeValue(valueStore.createIRI("urn:test:recover:second"));
		valueStore.commit();
		long secondValue = ValueIds.getValue(secondId);
		// the reopen scan must recover the max assigned VALUE counter (compound id >> 7), not a
		// partially-shifted compound id: an inflated counter multiplies the consumed id space ~32x
		// per reopen and would exhaust the 57-bit value space after a few dozen reopen cycles
		assertTrue(
				"value counter must continue compactly across reopen: first=" + firstValue + " second=" + secondValue,
				secondValue <= firstValue + 16);
	}

	@Test
	public void resolveValuesUsesSingleReadTransactionForOneRevision() throws Exception {
		CountingValueStore countingValueStore = new CountingValueStore(new File(dataDir, "resolve-values"),
				new LmdbStoreConfig());
		try {
			LmdbBNode first = countingValueStore.createBNode("batch-resolve-first");
			LmdbBNode second = countingValueStore.createBNode("batch-resolve-second");
			countingValueStore.startTransaction(true);
			long firstId = countingValueStore.storeValue(first);
			long secondId = countingValueStore.storeValue(second);
			countingValueStore.commit();
			countingValueStore.clearCaches();
			LmdbValue lazyFirst = countingValueStore.getLazyValue(firstId);
			LmdbValue lazySecond = countingValueStore.getLazyValue(secondId);
			assertFalse(lazyFirst.isInitialized());
			assertFalse(lazySecond.isInitialized());
			TxnManager txnManager = countingValueStore.getTxnManager();
			long ordinaryAdmissionsBefore = txnManager.ordinaryAdmissions();
			long reservedAdmissionsBefore = txnManager.reservedAdmissions();
			LmdbValue[] values = { lazySecond, lazyFirst };
			lazyFirst.getValueStoreRevision().resolveValues(values, new int[] { 1, 0 }, values.length);
			assertTrue(lazyFirst.isInitialized());
			assertTrue(lazySecond.isInitialized());
			assertEquals(first, lazyFirst);
			assertEquals(second, lazySecond);
			assertEquals(first.getID(), ((LmdbBNode) lazyFirst).getID());
			assertEquals(second.getID(), ((LmdbBNode) lazySecond).getID());
			assertEquals("a same-revision batch should own one ordinary read admission", 1,
					txnManager.ordinaryAdmissions() - ordinaryAdmissionsBefore);
			assertEquals("a same-revision batch should not borrow the reserved reader slot", 0,
					txnManager.reservedAdmissions() - reservedAdmissionsBefore);
		} finally {
			countingValueStore.close();
		}
	}

