	@ParameterizedTest
	@CsvSource({ "false,false", "true,false", "false,true", "true,true" })
	public void testReadyWriterValueDoesNotPublishIdDuringRollbackCleanup(boolean nested, boolean failedCommit)
			throws Exception {
		valueStore.close();
		CountDownLatch nativeAborted = new CountDownLatch(1);
		CountDownLatch releaseCleanup = new CountDownLatch(1);
		AtomicBoolean pauseCleanup = new AtomicBoolean();
		AtomicBoolean failNativeCommit = new AtomicBoolean();
		valueStore = new ValueStore(new File(dataDir, "values"), new LmdbStoreConfig()) {

			@Override
			int commitWriteTransaction(long transaction) {
				if (failNativeCommit.compareAndSet(true, false)) {
					mdb_txn_abort(transaction);
					return MDB_BAD_TXN;
				}
				return super.commitWriteTransaction(transaction);
			}

			@Override
			void rollbackRetiredIds() {
				if (pauseCleanup.compareAndSet(true, false)) {
					nativeAborted.countDown();
					try {
						assertTrue("The test must release the post-native-abort cleanup boundary",
								releaseCleanup.await(10, TimeUnit.SECONDS));
					} catch (InterruptedException e) {
						Thread.currentThread().interrupt();
						throw new SailException(e);
					}
				}
				super.rollbackRetiredIds();
			}
		};
		LmdbValue ready = readyWriterValue(nested);
		ExecutorService writer = Executors.newSingleThreadExecutor();
		Future<?> rollback = writer.submit(() -> {
			valueStore.startTransaction(true);
			valueStore.storeValue(ready);
			pauseCleanup.set(true);
			if (failedCommit) {
				failNativeCommit.set(true);
				assertThrows(IOException.class, valueStore::commit);
			} else {
				valueStore.rollback();
			}
			return null;
		});
		try {
			assertTrue("The actual native abort must finish before its metadata cleanup is paused",
					nativeAborted.await(5, TimeUnit.SECONDS));
			assertEquals("An aborted ready value cannot publish its old ID while writer state is being cleared",
					LmdbValue.UNKNOWN_ID, valueStore.getId(ready));
			releaseCleanup.countDown();
			rollback.get(5, TimeUnit.SECONDS);
			assertEquals(LmdbValue.UNKNOWN_ID, valueStore.getId(ready));
		} finally {
			releaseCleanup.countDown();
			try {
				rollback.get(5, TimeUnit.SECONDS);
			} finally {
				writer.shutdownNow();
				assertTrue(writer.awaitTermination(5, TimeUnit.SECONDS));
			}
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	public void testOlderCommitResetCannotPublishAbortedIdsDuringNextWriterCleanup(boolean nested) throws Exception {
		valueStore.close();
		CountDownLatch nativeAborted = new CountDownLatch(1);
		CountDownLatch releaseCleanup = new CountDownLatch(1);
		AtomicBoolean pauseCleanup = new AtomicBoolean();
		valueStore = new ValueStore(new File(dataDir, "values"), new LmdbStoreConfig()) {

			@Override
			void rollbackRetiredIds() {
				if (pauseCleanup.compareAndSet(true, false)) {
					nativeAborted.countDown();
					try {
						assertTrue(releaseCleanup.await(10, TimeUnit.SECONDS));
					} catch (InterruptedException interrupted) {
						Thread.currentThread().interrupt();
						throw new SailException(interrupted);
					}
				}
				super.rollbackRetiredIds();
			}
		};
		var manager = valueStore.getTxnManager().lockManager();
		long heldRead = manager.readLock();
		AtomicReference<Thread> committingThread = new AtomicReference<>();
		LmdbValue ready = readyWriterValue(nested);
		try (ExecutorService executor = Executors.newFixedThreadPool(2)) {
			Future<?> first = executor.submit(() -> {
				committingThread.set(Thread.currentThread());
				valueStore.startTransaction(true);
				valueStore.storeValue(Values.bnode("older-reset-committed"));
				valueStore.commit();
				return null;
			});
			try {
				while (committingThread.get() == null) {
					Thread.yield();
				}
				awaitWriterPublicationAfterNativeCommit(first, committingThread.get());
				Future<?> second = executor.submit(() -> {
					valueStore.startTransaction(true);
					valueStore.storeValue(ready);
					pauseCleanup.set(true);
					valueStore.rollback();
					return null;
				});
				try {
					assertTrue(nativeAborted.await(5, TimeUnit.SECONDS));
					manager.unlockRead(heldRead);
					heldRead = 0;
					first.get(5, TimeUnit.SECONDS);
					assertEquals("An older reset cannot reopen lookup proof during another writer's aborted-ID cleanup",
							LmdbValue.UNKNOWN_ID, valueStore.getId(ready));
				} finally {
					releaseCleanup.countDown();
					second.get(5, TimeUnit.SECONDS);
				}
			} finally {
				if (heldRead != 0) {
					manager.unlockRead(heldRead);
				}
				releaseCleanup.countDown();
				first.get(5, TimeUnit.SECONDS);
			}
		}
	}

	@Test
	public void testMissingCountWithoutNewReferenceCollectsQueuedComponent() throws Exception {
		IRI datatype = Values.iri("urn:refcount:missing-without-new-reference");
		valueStore.startTransaction(true);
		long literalId = valueStore.storeValue(Values.literal("only literal", datatype));
		valueStore.commit();
		long datatypeId = valueStore.getId(datatype);
		replaceLegacyRefCount(datatypeId, 0);
		valueStore.startTransaction(true);
		Set<Long> candidates = new HashSet<>();
		valueStore.gcIds(Set.of(literalId), candidates);
		assertEquals("An absent component count must stay at zero and enqueue the unreferenced component",
				Set.of(datatypeId), candidates);
		valueStore.gcIds(candidates, new HashSet<>());
		valueStore.commit();
		assertEquals(LmdbValue.UNKNOWN_ID, valueStore.getId(datatype));
		valueStore.close();
		valueStore = createValueStore();
		assertEquals(LmdbValue.UNKNOWN_ID, valueStore.getId(datatype));
	}

	private byte[] authoritativeDictionaryDigest(File directory) throws Exception {
		MessageDigest digest = MessageDigest.getInstance("SHA-256");
		return inspectNativeStore(directory, (stack, txn) -> {
			for (String database : Arrays.asList(null, TripleIndex.nativeDatabaseName("term-spoc", true),
					TripleIndex.nativeDatabaseName("term-cspo", true))) {
				PointerBuffer handle = stack.mallocPointer(1);
				E(mdb_cursor_open(txn, openDatabaseWithTxn(txn, database, 0), handle));
				long cursor = handle.get(0);
				try {
					MDBVal key = MDBVal.calloc(stack);
					MDBVal value = MDBVal.calloc(stack);
					for (int rc = mdb_cursor_get(cursor, key, value,
							MDB_FIRST); rc != MDB_NOTFOUND; rc = mdb_cursor_get(cursor, key, value, MDB_NEXT)) {
						E(rc);
						ByteBuffer bytes = key.mv_data();
						if (database != null || Byte
								.toUnsignedInt(bytes.get(bytes.position())) <= ValueStoreRecordCodec.NEXT_ID_KEY) {
							digest.update(ByteBuffer.allocate(Integer.BYTES).putInt(bytes.remaining()).flip());
							digest.update(bytes);
							digest.update(
									ByteBuffer.allocate(Integer.BYTES).putInt(value.mv_data().remaining()).flip());
							digest.update(value.mv_data());
						}
					}
				} finally {
					mdb_cursor_close(cursor);
				}
			}
			return digest.digest();
		});
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	public void testReclamationRejectsAnActiveForwardOwnerWithoutIncomingReferences(boolean tripleTerm)
			throws Exception {
		Value active = activeUnreferencedValue(tripleTerm);
		valueStore.startTransaction(true);
		long id = valueStore.storeValue(active);
		valueStore.commit();
		IOException failure = assertThrows(IOException.class, () -> valueStore.writeTransaction((stack, txn) -> {
			putUnusedHint(stack, txn, id);
			valueStore.freeUnusedIdsAndValues(stack, txn, null);
			return null;
		}));
		assertTrue(failure.getMessage(), failure.getMessage().contains("pending retirement for active value"));
		assertEquals(id, valueStore.getId(active));
		assertEquals(active, valueStore.getValue(id));
		assertEquals(0L, countValueDatabaseEntries("free_ids"));
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	public void testReclamationAcceptsRetiredReverseOnlyRecords(boolean tripleTerm) throws Exception {
		Value retired = activeUnreferencedValue(tripleTerm);
		valueStore.startTransaction(true);
		long id = valueStore.storeValue(retired);
		valueStore.commit();
		valueStore.startTransaction(true);
		valueStore.gcIds(Set.of(id), new HashSet<>());
		valueStore.commit();
		assertEquals(LmdbValue.UNKNOWN_ID, valueStore.getId(retired));
		assertEquals(1L, countValueDatabaseEntries("unused_ids"));
		valueStore.writeTransaction((stack, txn) -> {
			valueStore.freeUnusedIdsAndValues(stack, txn, null);
			return null;
		});
		assertEquals(0L, countValueDatabaseEntries("unused_ids"));
		assertEquals(1L, countValueDatabaseEntries("free_ids"));
		assertNull(valueStore.getValue(id));
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	public void testOwningRecoveryRejectsActiveDictionaryOwnerAbsentFromTriples(boolean tripleTerm) throws Exception {
		valueStore.close();
		File ownerDirectory = new File(dataDir, "owning-recovery");
		LmdbStoreConfig config = new LmdbStoreConfig().setSketchEstimatorEnabled(false);
		LmdbStore store = new LmdbStore(ownerDirectory, config);
		store.init();
		store.shutDown();
		File dictionaryDirectory = new File(ownerDirectory, "values");
		StoreProperties properties = new StoreProperties(ownerDirectory);
		assertTrue(properties.load());
		Value active = activeUnreferencedValue(tripleTerm);
		long id;
		byte[] reverse;
		long[] termQuad;
		ValueStore dictionary = new ValueStore(dictionaryDirectory, properties, config);
		try {
			dictionary.startTransaction(true);
			id = dictionary.storeValue(active);
			dictionary.commit();
			reverse = tripleTerm ? null : dictionary.getData(id).clone();
			termQuad = tripleTerm
					? new long[] { dictionary.getId(((TripleTerm) active).getSubject()),
							dictionary.getId(((TripleTerm) active).getPredicate()),
							dictionary.getId(((TripleTerm) active).getObject()), id }
					: null;
		} finally {
			dictionary.close();
		}
		mutateClosedNativeStore(dictionaryDirectory, (stack, txn) -> {
			putUnusedHint(stack, txn, id);
			return null;
		});
		for (int attempt = 0; attempt < 3; attempt++) {
			LmdbStore reopened = new LmdbStore(ownerDirectory, config);
			SailException failure = assertThrows(SailException.class, reopened::init);
			assertTrue(failure.getMessage(), failure.getMessage().contains("pending retirement for active value"));
			inspectNativeStore(dictionaryDirectory, (stack, txn) -> {
				assertActiveNativeOwner(stack, txn, id, reverse, termQuad);
				return null;
			});
		}
	}

	private Value activeUnreferencedValue(boolean tripleTerm) {
		return tripleTerm
				? Values.tripleTerm(Values.bnode("active-unreferenced-subject"),
						Values.iri("urn:active-unreferenced:predicate"), Values.literal("active unreferenced payload"))
				: Values.bnode("active-unreferenced-owner");
	}

	private void putUnusedHint(MemoryStack stack, long txn, long id) throws IOException {
		ByteBuffer bytes = stack.malloc(32);
		Varint.writeUnsigned(bytes, 1L);
		bytes.put(ValueStoreRecordCodec.ID_KEY);
		Varint.writeUnsigned(bytes, id);
		MDBVal key = MDBVal.calloc(stack).mv_data(bytes.flip());
		E(mdb_put(txn, openDatabaseWithTxn(txn, "unused_ids", 0), key, MDBVal.calloc(stack), 0));
	}

	private <T> T mutateClosedNativeStore(File directory, LmdbUtil.Transaction<T> mutation) throws IOException {
		return accessClosedNativeStore(directory, mutation, true);
	}

	private <T> T accessClosedNativeStore(File directory, LmdbUtil.Transaction<T> operation, boolean write)
			throws IOException {
		long env;
		try (MemoryStack stack = stackPush()) {
			PointerBuffer pp = stack.mallocPointer(1);
			E(mdb_env_create(pp));
			env = pp.get(0);
		}
		try {
			E(mdb_env_set_maxdbs(env, 18));
			E(mdb_env_open(env, directory.getAbsolutePath(), MDB_NOTLS, 0664));
			return write ? LmdbUtil.writeTransaction(env, operation) : LmdbUtil.readTransaction(env, operation);
		} finally {
			mdb_env_close(env);
		}
	}

	private void assertActiveNativeOwner(MemoryStack stack, long txn, long id, byte[] reverse, long[] termQuad)
			throws IOException {
		MDBVal key = MDBVal.calloc(stack);
		MDBVal data = MDBVal.calloc(stack);
		if (reverse != null) {
			key.mv_data(stack.bytes(ValueStoreRecordCodec.idKey(id)));
			assertEquals(MDB_SUCCESS, mdb_get(txn, openDatabaseWithTxn(txn, null, 0), key, data));
			byte[] actual = new byte[data.mv_size() == 0 ? 0 : Math.toIntExact(data.mv_size())];
			data.mv_data().get(actual);
			assertArrayEquals("The reverse record must remain exact", reverse, actual);
			byte[] forward = reverse.length <= ValueStoreRecordCodec.MAX_INLINE_KEY_BYTES ? reverse
					: ValueStoreRecordCodec.hashKey(ValueStoreRecordCodec.hash(reverse));
			key.mv_data(stack.bytes(forward));
			int result = mdb_get(txn, openDatabaseWithTxn(txn, null, 0), key, data);
			if (result != MDB_SUCCESS || nativeIdFromAssociation(key, data) != id) {
				assertTrue("only a colliding hash owner needs its per-ID association",
						reverse.length > ValueStoreRecordCodec.MAX_INLINE_KEY_BYTES);
				forward = ValueStoreRecordCodec.collisionKey(ValueStoreRecordCodec.hash(reverse), id);
				key.mv_data(stack.bytes(forward));
				result = mdb_get(txn, openDatabaseWithTxn(txn, null, 0), key, data);
			}
			assertEquals("The active forward record must remain", MDB_SUCCESS, result);
			assertEquals(id, nativeIdFromAssociation(key, data));
		} else {
			for (String order : List.of("spoc", "cspo")) {
				ByteBuffer bytes = stack.malloc(TripleIndex.MAX_KEY_LENGTH);
				IndexKeyWriters.forFieldSeq(order)
						.write(bytes, termQuad[0], termQuad[1], termQuad[2], termQuad[3], false);
				key.mv_data(bytes.flip());
				assertEquals("The active term's " + order + " record must remain", MDB_SUCCESS, mdb_get(txn,
						openDatabaseWithTxn(txn, TripleIndex.nativeDatabaseName("term-" + order, true), 0), key, data));
			}
		}
	}

	private void assertRefCountCompletionUntrusted(MemoryStack stack, long txn) throws IOException {
		MDBVal key = MDBVal.calloc(stack);
		key.mv_data(stack.bytes((byte) 0));
		MDBVal data = MDBVal.calloc(stack);
		int result = mdb_get(txn, openDatabaseWithTxn(txn, "ref_counts", 0), key, data);
		assertTrue("Failed recovery cannot publish clean reference-count completion",
				result == MDB_NOTFOUND || result == MDB_SUCCESS && data.mv_data().get(Integer.BYTES + 1) == 0);
	}

	private void removeClosedRefCountMarker(File directory) throws IOException {
		mutateClosedNativeStore(directory, (stack, txn) -> {
			MDBVal key = MDBVal.calloc(stack);
			key.mv_data(stack.bytes((byte) 0));
			E(mdb_del(txn, openDatabaseWithTxn(txn, "ref_counts", 0), key, null));
			return null;
		});
	}

	private void replaceRefCount(MemoryStack stack, long txn, long id, long count) throws IOException {
		int countsDbi = openDatabaseWithTxn(txn, "ref_counts", 0);
		// Missing-marker recovery uses the actual current codec, not a historical key approximation.
		E(mdb_drop(txn, countsDbi, false));
		if (count != 0) {
			MDBVal key = MDBVal.calloc(stack);
			key.mv_data(valueStore.id2data(valueStore.idBuffer(stack), id).flip());
			MDBVal data = MDBVal.calloc(stack);
			ByteBuffer countBuffer = stack.malloc(Long.BYTES + 1);
			Varint.writeUnsigned(countBuffer, count);
			data.mv_data(countBuffer.flip());
			E(mdb_put(txn, countsDbi, key, data, 0));
		}
	}

	@Test
	public void testCoreDatatypeCounterSurvivesTermIndexInitialization() throws Exception {
		valueStore.close();
		StoreProperties properties = new StoreProperties()
				.setLiteralReferenceEncoding(StoreProperties.LITERAL_REFERENCE_ENCODING_CORE_V1);
		LmdbStoreConfig config = new LmdbStoreConfig().setInlineLiterals(false);
		File directory = new File(dataDir, "core-counter");
		valueStore = new ValueStore(directory, properties, config);
		valueStore.startTransaction(true);
		long lastId = 0;
		for (int i = 0; i < 10; i++) {
			lastId = valueStore.storeValue(Values.literal("before-reopen-" + i));
		}
		valueStore.commit();
		valueStore.close();
		valueStore = new ValueStore(directory, properties, config);
		long next = valueStore.storeValue(Values.literal("after-reopen"));
		assertTrue("opening triple-term indexes must preserve the persisted dictionary counter",
				ValueIds.referenceOrdinal(next) > ValueIds.referenceOrdinal(lastId));
		assertEquals(Values.literal("before-reopen-9"), valueStore.getValue(lastId));
	}

	@Test
	public void testRepeatedTripleTermIteratorCloseDoesNotReleaseAnotherLease() throws Exception {
		TxnManager manager = valueStore.getTxnManager();
		RecordIterator iterator = valueStore.getTripleTerms(-1, -1, -1);
		iterator.close();
		List<Txn> held = new ArrayList<>();
		try {
			for (int i = 0; i < TxnManager.POOL_SIZE - 1; i++) {
				held.add(manager.createReadTxn());
			}
			assertEquals(0, manager.availableReadTxnSlots(TxnManager.POOL_SIZE, 0));
			iterator.close();
			assertEquals("a closed iterator must not return a reader that has been lent to another caller", 0,
					manager.availableReadTxnSlots(TxnManager.POOL_SIZE, 0));
		} finally {
			held.forEach(Txn::close);
		}
	}

	@Test
	public void testLongLanguageLiteralRoundTripsThroughSharedCodec() throws Exception {
		List<Literal> literals = new ArrayList<>();
		for (String language : List.of("en-x-" + "abcdefgh-".repeat(6) + "abcd",
				"en-x-" + "abcdefgh-".repeat(6) + "abcde", "en-x-" + "abcdefgh-".repeat(14) + "abcdefgh")) {
			literals.add(SimpleValueFactory.getInstance().createLiteral("long language value", language));
			for (Literal.BaseDirection direction : Literal.BaseDirection.values()) {
				literals.add(SimpleValueFactory.getInstance()
						.createLiteral("directed long language value", language, direction));
			}
		}
		long[] ids = new long[literals.size()];
		valueStore.startTransaction(true);
		for (int i = 0; i < ids.length; i++) {
			ids[i] = valueStore.storeValue(literals.get(i));
		}
		valueStore.commit();
		reopenValueStore(new LmdbStoreConfig());
		for (int i = 0; i < ids.length; i++) {
			Literal resolved = (Literal) valueStore.getValue(ids[i]);
			assertEquals(literals.get(i).getLanguage(), resolved.getLanguage());
			assertEquals(literals.get(i).getBaseDirection(), resolved.getBaseDirection());
			assertEquals(literals.get(i), resolved);
		}
	}
